insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('cf000000-0000-0000-0000-000000000001', 'ukmla', '93b4abaa-2ded-4421-b7b1-72109dc2200c',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('cf000000-0000-0000-0000-000000000001', 'A', 'Arrange an outpatient temporal artery biopsy and start steroids only if it is positive', false, 'Ruled out because delaying treatment until biopsy confirmation risks irreversible bilateral blindness; steroids must be started empirically on clinical suspicion and biopsy performed afterwards (ideally within 1-2 weeks, without stopping steroids).', 1),
('cf000000-0000-0000-0000-000000000001', 'B', 'Refer routinely to ophthalmology outpatients for review within 2 weeks', false, 'Ruled out because this is an ophthalmic and rheumatological emergency; any delay risks permanent loss of vision in this eye and imminent involvement of the other eye.', 2),
('cf000000-0000-0000-0000-000000000001', 'C', 'Start high-dose oral prednisolone immediately, before temporal artery biopsy results are available', true, 'Correct. This presentation (jaw claudication, scalp tenderness, raised inflammatory markers, and sudden visual loss with a swollen pale disc) is classic for giant cell arteritis causing arteritic anterior ischaemic optic neuropathy. High-dose corticosteroids must be started immediately on clinical suspicion to protect the contralateral eye; biopsy should be arranged within days but treatment must never be delayed for it.', 3),
('cf000000-0000-0000-0000-000000000001', 'D', 'Start a course of oral NSAIDs for symptomatic headache relief', false, 'Ruled out because NSAIDs do not address the underlying vasculitis and will not prevent progression to bilateral blindness; high-dose corticosteroids are required urgently.', 4),
('cf000000-0000-0000-0000-000000000001', 'E', 'Discharge with safety-net advice to return if vision worsens further', false, 'Ruled out because vision loss has already occurred and the fellow eye remains at imminent risk; this requires immediate treatment, not discharge.', 5),
('cf000000-0000-0000-0000-000000000002', 'A', 'Reassure the patient that vision will return spontaneously within 24 hours', false, 'Ruled out because CRAO causes retinal infarction; without prompt treatment (which is rarely successful after this time window) vision usually does not recover, and this presentation instead signals systemic embolic risk requiring urgent stroke-pathway assessment.', 1),
('cf000000-0000-0000-0000-000000000002', 'B', 'Arrange a routine ophthalmology outpatient appointment for the next available clinic slot', false, 'Ruled out because CRAO is an ocular emergency and a marker of systemic vascular disease; it requires same-day urgent assessment, not routine outpatient booking.', 2),
('cf000000-0000-0000-0000-000000000002', 'C', 'Start topical antibiotic drops and review in one week', false, 'Ruled out because there is no infective process here; topical antibiotics have no role and this delay ignores an emergency requiring urgent systemic vascular assessment.', 3),
('cf000000-0000-0000-0000-000000000002', 'D', 'Immediate referral to the eye casualty/stroke pathway for urgent assessment as an ocular stroke', true, 'Correct. A cherry-red spot with pale retina and sudden painless monocular visual loss is diagnostic of central retinal artery occlusion, which is a retinal stroke. It requires the same urgent vascular work-up as a cerebral stroke (looking for a cardioembolic or carotid source) and time-critical assessment, even though visual outcomes are often poor once vision has been lost for this long.', 4),
('cf000000-0000-0000-0000-000000000002', 'E', 'Prescribe oral prednisolone and review in the community', false, 'Ruled out because there are no features suggesting giant cell arteritis (no headache, scalp tenderness or jaw claudication described) and steroids are not the management of embolic CRAO.', 5),
('cf000000-0000-0000-0000-000000000003', 'A', 'Reassure that floaters are a normal ageing change and review in six weeks', false, 'Ruled out because although isolated floaters can be benign vitreous degeneration, the combination of new flashes, floaters and an advancing field defect (curtain) strongly suggests retinal detachment, which needs same-day assessment, not reassurance.', 1),
('cf000000-0000-0000-0000-000000000003', 'B', 'Urgent same-day referral to ophthalmology for assessment', true, 'Correct. New flashes, floaters and a curtain-like field defect in a myopic patient are highly suggestive of a rhegmatogenous retinal detachment, which is a sight-threatening emergency requiring same-day ophthalmic assessment, since the macula may still be attached and salvageable with prompt surgery.', 2),
('cf000000-0000-0000-0000-000000000003', 'C', 'Prescribe topical steroid drops and review in one week', false, 'Ruled out because there is no inflammatory process here; topical steroids play no role in suspected retinal detachment, which requires urgent surgical referral.', 3),
('cf000000-0000-0000-0000-000000000003', 'D', 'Arrange an outpatient MRI brain to investigate the visual symptoms', false, 'Ruled out because this presentation is characteristic of a primary retinal problem, not an intracranial one; the correct next step is direct ophthalmic examination, not neuroimaging.', 4),
('cf000000-0000-0000-0000-000000000003', 'E', 'Advise the patient to rest and avoid bending over, with review in two weeks', false, 'Ruled out because a symptomatic retinal detachment threatens the macula and central vision the longer it is left; delaying assessment for two weeks risks permanent visual loss and this needs same-day ophthalmology review.', 5),
('cf000000-0000-0000-0000-000000000004', 'A', 'Central retinal artery occlusion', false, 'Ruled out because CRAO produces a pale, oedematous retina with a cherry-red spot and no haemorrhages, which is a different picture from the widespread haemorrhagic fundus described here.', 1),
('cf000000-0000-0000-0000-000000000004', 'B', 'Vitreous haemorrhage', false, 'Ruled out because vitreous haemorrhage causes a hazy, obscured red reflex and floaters with an often poorly visualised fundus, rather than the well-defined pattern of retinal haemorrhages and venous changes described.', 2),
('cf000000-0000-0000-0000-000000000004', 'C', 'Anterior uveitis', false, 'Ruled out because uveitis presents with a painful red eye, photophobia and anterior chamber inflammation, not painless vision loss with this fundal haemorrhagic appearance.', 3),
('cf000000-0000-0000-0000-000000000004', 'D', 'Optic neuritis', false, 'Ruled out because optic neuritis typically causes painful visual loss (worse on eye movement) in a younger patient, with a normal or mildly swollen disc but not widespread four-quadrant retinal haemorrhages.', 4),
('cf000000-0000-0000-0000-000000000004', 'E', 'Central retinal vein occlusion', true, $x$Correct. Diffuse flame and blot haemorrhages in all four quadrants with disc swelling and venous dilatation and tortuosity ('stormy sunset fundus') is the classic appearance of central retinal vein occlusion, strongly associated with hypertension, as here.$x$, 5),
('cf000000-0000-0000-0000-000000000005', 'A', 'Vitreous haemorrhage secondary to proliferative diabetic retinopathy', true, 'Correct. Sudden painless floaters and visual loss with a hazy red reflex and obscured fundus view in a patient with long-standing poorly controlled diabetes strongly suggests bleeding from fragile new vessels (neovascularisation) into the vitreous cavity, characteristic of proliferative diabetic retinopathy.', 1),
('cf000000-0000-0000-0000-000000000005', 'B', 'Central retinal artery occlusion', false, 'Ruled out because CRAO produces a pale retina and cherry-red spot with a normal red reflex and clear view to the retina, not a hazy obscured fundus from blood in the vitreous.', 2),
('cf000000-0000-0000-0000-000000000005', 'C', 'Acute angle closure glaucoma', false, 'Ruled out because angle closure typically causes a painful red eye with a hazy cornea and fixed dilated pupil, not painless floaters with vitreous haemorrhage obscuring the fundus.', 3),
('cf000000-0000-0000-0000-000000000005', 'D', 'Retinal migraine', false, 'Ruled out because retinal migraine causes transient, fully reversible monocular visual disturbance typically lasting minutes to an hour, not a persistent haemorrhage obscuring fundal view.', 4),
('cf000000-0000-0000-0000-000000000005', 'E', 'Cataract progression', false, 'Ruled out because cataract causes gradual, progressive blurring of vision over months to years with a hazy red reflex from lens opacity, not sudden floaters with an acutely obscured fundus.', 5),
('cf000000-0000-0000-0000-000000000006', 'A', 'Reassure that this is expected progression of dry AMD and review in six months', false, 'Ruled out because rapid new distortion and vision loss over days is not typical of slowly progressive dry AMD; it suggests conversion to the wet form, which requires urgent treatment, not routine follow-up.', 1),
('cf000000-0000-0000-0000-000000000006', 'B', 'Urgent (same-week) referral to ophthalmology for assessment for anti-VEGF therapy', true, 'Correct. New metamorphopsia and rapid central visual decline in a patient with known AMD is a classic presentation of conversion from dry to wet (neovascular) AMD, which needs urgent assessment as anti-VEGF injections are time-critical to prevent further vision loss from subretinal neovascular membrane growth and bleeding.', 2),
('cf000000-0000-0000-0000-000000000006', 'C', 'Start oral high-dose vitamin and mineral supplementation alone', false, 'Ruled out because AREDS-type supplementation may reduce progression risk in dry AMD but does not treat active wet AMD; this presentation needs urgent referral for anti-VEGF therapy.', 3),
('cf000000-0000-0000-0000-000000000006', 'D', 'Arrange routine cataract surgery assessment', false, 'Ruled out because there is no suggestion of cataract here (no gradual glare or progressive blur over months); the acute distortion and scotoma point to macular pathology needing urgent same-week referral.', 4),
('cf000000-0000-0000-0000-000000000006', 'E', 'Prescribe topical antibiotic drops for a presumed infective cause', false, 'Ruled out because there are no infective features (no discharge, redness, or foreign body sensation); this is a macular problem requiring specialist retinal assessment, not antibiotics.', 5),
('cf000000-0000-0000-0000-000000000007', 'A', 'MRI of the brain and orbits with contrast', true, 'Correct. Painful unilateral visual loss with reduced colour vision, a relative afferent pupillary defect and disc swelling in a young adult is characteristic of optic neuritis. Given the prior neurological episode suggestive of a previous demyelinating event, MRI brain and orbits is the key investigation to look for demyelinating lesions and assess the risk of multiple sclerosis.', 1),
('cf000000-0000-0000-0000-000000000007', 'B', 'Temporal artery biopsy', false, 'Ruled out because there are no features of giant cell arteritis (this patient is young, with no headache, scalp tenderness or jaw claudication, and GCA is rare under 50); biopsy is not indicated here.', 2),
('cf000000-0000-0000-0000-000000000007', 'C', 'Slit-lamp examination and intraocular pressure measurement alone', false, 'Ruled out because although a full eye examination is part of assessment, the key diagnostic step to confirm optic neuritis and evaluate for underlying demyelinating disease is MRI, especially given the prior neurological symptom.', 3),
('cf000000-0000-0000-0000-000000000007', 'D', 'Carotid Doppler ultrasound', false, 'Ruled out because there is no history suggesting embolic or vascular visual loss (such as transient monocular visual loss or amaurosis fugax); the clinical picture points to optic neuritis, for which MRI is the key investigation.', 4),
('cf000000-0000-0000-0000-000000000007', 'E', 'Reassurance and review in six weeks with no imaging', false, 'Ruled out because a first episode of optic neuritis, especially with a preceding suggestive neurological event, warrants prompt investigation with MRI to risk-stratify for multiple sclerosis and guide management.', 5),
('cf000000-0000-0000-0000-000000000008', 'A', 'Reassure the patient that this is likely migraine and no further action is needed', false, $x$Ruled out because although retinal migraine exists, the vascular risk factor profile and stereotyped 'curtain' description make embolic amaurosis fugax the priority diagnosis to exclude, given the high risk of impending stroke; migraine should not be assumed without urgent assessment first.$x$, 1),
('cf000000-0000-0000-0000-000000000008', 'B', 'Book a routine ophthalmology outpatient appointment in six weeks', false, 'Ruled out because transient monocular vision loss with vascular risk factors requires same-day TIA-pathway assessment, not a routine, delayed ophthalmology appointment.', 2),
('cf000000-0000-0000-0000-000000000008', 'C', 'Arrange an MRI brain as an outpatient within the next month', false, 'Ruled out because this presentation needs same-day, not delayed, urgent assessment; the priority is rapid carotid and cardiovascular risk assessment along with immediate antiplatelet therapy.', 3),
('cf000000-0000-0000-0000-000000000008', 'D', 'Start a statin only and review in primary care in two weeks', false, 'Ruled out because statin therapy alone, without same-day specialist assessment, aspirin and carotid imaging, does not adequately address the high short-term stroke risk after amaurosis fugax.', 4),
('cf000000-0000-0000-0000-000000000008', 'E', 'Same-day referral for urgent TIA assessment, including carotid imaging, and start aspirin immediately', true, $x$Correct. Transient, fully reversible monocular visual loss ('curtain' descending and lifting) in a patient with vascular risk factors is amaurosis fugax, a retinal TIA usually caused by embolism from carotid atherosclerosis. It should be treated with the same urgency as any TIA: immediate aspirin (in the absence of contraindication) and same-day specialist assessment with carotid imaging, given the high short-term risk of stroke.$x$, 5),
('cf000000-0000-0000-0000-000000000009', 'A', 'Reassure and arrange review with community optometry in three months', false, 'Ruled out because bilateral papilloedema signals raised intracranial pressure, which risks permanent optic nerve damage and visual loss if untreated; this requires urgent same-admission investigation, not routine optometric review.', 1),
('cf000000-0000-0000-0000-000000000009', 'B', 'Perform lumbar puncture immediately without prior neuroimaging', false, 'Ruled out because lumbar puncture before imaging risks precipitating brainstem herniation if there is an unsuspected space-occupying lesion; neuroimaging must be performed first to exclude a mass or venous sinus thrombosis.', 2),
('cf000000-0000-0000-0000-000000000009', 'C', 'Start oral corticosteroids empirically for presumed optic neuritis', false, 'Ruled out because the bilateral disc swelling with headache and positional visual obscurations is not typical of optic neuritis (usually unilateral, painful, with reduced acuity), and steroids are not the correct next step before establishing the diagnosis of raised intracranial pressure.', 3),
('cf000000-0000-0000-0000-000000000009', 'D', 'Urgent MRI/MRV brain, followed by lumbar puncture with opening pressure measurement if imaging is normal', true, 'Correct. Bilateral papilloedema with headache and transient visual obscurations in an obese young woman is highly suggestive of idiopathic intracranial hypertension, but any cause of bilateral disc swelling must first be investigated with neuroimaging (to exclude a mass lesion or venous sinus thrombosis) before a lumbar puncture is performed to confirm raised opening pressure and allow therapeutic drainage.', 4),
('cf000000-0000-0000-0000-000000000009', 'E', 'Arrange outpatient visual field testing only, with no imaging', false, 'Ruled out because although visual fields are important for monitoring, the urgent priority is to investigate and exclude a structural or vascular cause of raised intracranial pressure with imaging before any lumbar puncture.', 5),
('cf000000-0000-0000-0000-000000000010', 'A', 'Prescribe oral antibiotics and review in the community in 48 hours', false, 'Ruled out because oral antibiotics do not achieve adequate intravitreal concentrations to treat endophthalmitis; this requires emergency intravitreal therapy and urgent same-day ophthalmic assessment, not delayed community review.', 1),
('cf000000-0000-0000-0000-000000000010', 'B', 'Reassure that this is expected postoperative inflammation and continue routine follow-up', false, 'Ruled out because hypopyon with worsening pain and dramatic visual decline days after cataract surgery is not routine postoperative inflammation; it indicates infective endophthalmitis, a vision- and eye-threatening emergency.', 2),
('cf000000-0000-0000-0000-000000000010', 'C', 'Emergency same-day referral to ophthalmology for urgent intravitreal antibiotics/sampling', true, 'Correct. Increasing pain, redness, reduced vision and hypopyon within days of intraocular surgery is characteristic of postoperative endophthalmitis, a sight-threatening emergency caused by intraocular infection. It requires emergency same-day ophthalmic assessment for vitreous/aqueous sampling and immediate intravitreal antibiotics (sometimes with vitrectomy), as delay risks irreversible loss of the eye.', 3),
('cf000000-0000-0000-0000-000000000010', 'D', $x$Increase the frequency of the patient's routine postoperative topical steroid drops only$x$, false, 'Ruled out because increasing topical steroids alone does not treat underlying intraocular infection and may worsen it; the priority is emergency referral for intravitreal antibiotic treatment and sampling.', 4),
('cf000000-0000-0000-0000-000000000010', 'E', 'Arrange non-urgent outpatient ophthalmology review within one week', false, 'Ruled out because postoperative endophthalmitis can cause rapid, permanent loss of vision within days; it requires same-day emergency assessment, not a delayed outpatient appointment.', 5),
('cf000000-0000-0000-0000-000000000011', 'A', 'Urgent same-day referral to ophthalmology', false, 'Ruled out because blepharitis is a common, chronic, benign condition without visual threat; it is managed in primary care with lid hygiene, not urgent referral.', 1),
('cf000000-0000-0000-0000-000000000011', 'B', 'Lid hygiene with warm compresses and gentle lid margin cleaning', true, 'Correct. Chronic bilateral gritty, crusty eyes with lid margin telangiectasia and lash flaking is characteristic of blepharitis (meibomian gland dysfunction). First-line management is regular lid hygiene: warm compresses to loosen debris and soften meibomian secretions, followed by gentle mechanical cleaning of the lid margins.', 2),
('cf000000-0000-0000-0000-000000000011', 'C', 'Topical chloramphenicol drops as first-line treatment', false, 'Ruled out because there is no evidence of acute bacterial infection here (no purulent discharge); first-line management of blepharitis is lid hygiene, with antibiotics reserved for more severe or refractory cases.', 3),
('cf000000-0000-0000-0000-000000000011', 'D', 'Oral high-dose corticosteroids', false, 'Ruled out because systemic steroids are not indicated for this chronic, low-grade lid margin condition and carry unnecessary risk; lid hygiene is the appropriate first step.', 4),
('cf000000-0000-0000-0000-000000000011', 'E', 'Immediate surgical excision of the eyelid margin', false, 'Ruled out because blepharitis is a medical, not surgical, condition; there is no role for excisional surgery in its management.', 5),
('cf000000-0000-0000-0000-000000000012', 'A', 'Hordeolum (stye); prescribe oral antibiotics immediately', false, 'Ruled out because a hordeolum is typically painful, tender, and points at the lash line, unlike this painless, firm, deep tarsal nodule; oral antibiotics are not first-line for either condition in the absence of spreading infection.', 1),
('cf000000-0000-0000-0000-000000000012', 'B', 'Basal cell carcinoma; arrange urgent 2-week-wait referral', false, 'Ruled out because a BCC typically presents in an older patient as a slowly enlarging, ulcerated or pearly lesion with telangiectasia, not an acute painless firm tarsal nodule in a 38-year-old, which is much more consistent with a benign chalazion.', 2),
('cf000000-0000-0000-0000-000000000012', 'C', 'Chalazion; manage conservatively with warm compresses, as most resolve spontaneously', true, 'Correct. A painless, firm, non-tender nodule within the eyelid (tarsal plate) is typical of a chalazion, caused by a blocked meibomian gland. Most resolve spontaneously over weeks with conservative measures such as warm compresses and gentle massage; incision and curettage is reserved for persistent lesions.', 3),
('cf000000-0000-0000-0000-000000000012', 'D', 'Orbital cellulitis; admit for intravenous antibiotics', false, 'Ruled out because there is no proptosis, painful eye movement, visual disturbance or systemic illness; this is a localised, benign eyelid lesion, not orbital cellulitis.', 4),
('cf000000-0000-0000-0000-000000000012', 'E', 'Dacryocystitis; arrange incision and drainage of the lacrimal sac', false, 'Ruled out because dacryocystitis causes a painful swelling at the medial canthus overlying the lacrimal sac, not a nodule within the eyelid tarsal plate.', 5),
('cf000000-0000-0000-0000-000000000013', 'A', 'Admit for intravenous antibiotics', false, 'Ruled out because there are no features of orbital cellulitis (no proptosis, no painful or restricted eye movements, no systemic illness); a simple stye does not require admission or intravenous treatment.', 1),
('cf000000-0000-0000-0000-000000000013', 'B', 'Urgent incision and drainage under general anaesthetic', false, 'Ruled out because most styes drain spontaneously with conservative measures such as warm compresses; surgical drainage is reserved for lesions that fail to resolve, and general anaesthesia is not needed for such a minor procedure.', 2),
('cf000000-0000-0000-0000-000000000013', 'C', 'Oral high-dose corticosteroids', false, 'Ruled out because a stye is an infective process; steroids are not appropriate and could worsen infection.', 3),
('cf000000-0000-0000-0000-000000000013', 'D', 'Warm compresses several times a day, with topical antibiotic ointment if it persists', true, 'Correct. A tender, pointing pustule at the eyelash margin is a classic external hordeolum (stye), caused by acute infection of a lash follicle gland. First-line management is warm compresses to encourage spontaneous drainage, with topical antibiotics considered if it persists or there is associated conjunctivitis.', 4),
('cf000000-0000-0000-0000-000000000013', 'E', 'Reassure with no treatment as it will not improve with any intervention', false, 'Ruled out because while many styes resolve on their own, warm compresses accelerate resolution and reduce discomfort, so some initial conservative management should be offered rather than no advice at all.', 5),
('cf000000-0000-0000-0000-000000000014', 'A', 'Involutional entropion', true, 'Correct. Inward rotation of the eyelid margin causing lashes to rub against the cornea (trichiasis-like irritation) with corneal punctate staining, in an elderly patient without other cause, is typical of involutional (age-related) entropion, due to age-related laxity of the lower lid retractors and orbicularis muscle overriding the tarsal plate.', 1),
('cf000000-0000-0000-0000-000000000014', 'B', 'Ectropion', false, 'Ruled out because ectropion is outward turning of the lid margin, causing exposure and watering, which is the opposite finding to the inward-turning lid described here.', 2),
('cf000000-0000-0000-0000-000000000014', 'C', 'Blepharitis', false, 'Ruled out because blepharitis causes lid margin inflammation and crusting without structural malposition of the lid margin; here there is a clear anatomical inward turning of the lid.', 3),
('cf000000-0000-0000-0000-000000000014', 'D', 'Preseptal cellulitis', false, 'Ruled out because there is no swelling, erythema or acute infective feature described; this is a chronic mechanical lid malposition problem, not an infective one.', 4),
('cf000000-0000-0000-0000-000000000014', 'E', 'Chalazion', false, 'Ruled out because a chalazion is a discrete lid nodule, not a diffuse malposition of the lid margin causing lash-corneal contact.', 5),
('cf000000-0000-0000-0000-000000000015', 'A', 'Entropion', false, 'Ruled out because entropion is inward turning of the lid margin causing lash-corneal irritation, the opposite of the outward-turning lid margin described here.', 1),
('cf000000-0000-0000-0000-000000000015', 'B', 'Acute dacryocystitis', false, 'Ruled out because dacryocystitis presents with a painful, red swelling over the lacrimal sac at the medial canthus, not a structural eyelid malposition.', 2),
('cf000000-0000-0000-0000-000000000015', 'C', 'Allergic conjunctivitis', false, 'Ruled out because allergic conjunctivitis causes bilateral itching and chemosis, not a unilateral structural lid malposition following facial nerve palsy.', 3),
('cf000000-0000-0000-0000-000000000015', 'D', 'Trichiasis', false, 'Ruled out because trichiasis is misdirected eyelashes rubbing the eye with a normally positioned lid margin, not outward rotation of the whole lid.', 4),
('cf000000-0000-0000-0000-000000000015', 'E', 'Ectropion secondary to facial nerve palsy', true, 'Correct. Outward turning of the eyelid margin (ectropion) in the context of facial nerve palsy is a recognised complication, occurring because weakness of the orbicularis oculi fails to hold the lid against the globe, leading to exposure, watering (epiphora, paradoxically from poor tear drainage and reflex tearing) and risk of exposure keratopathy.', 5),
('cf000000-0000-0000-0000-000000000016', 'A', 'Orbital cellulitis; admit immediately for intravenous antibiotics', false, 'Ruled out because the hallmark features of orbital cellulitis - proptosis, painful or restricted eye movements, or reduced vision - are absent here; this presentation is consistent with the less severe preseptal cellulitis.', 1),
('cf000000-0000-0000-0000-000000000016', 'B', 'Allergic eyelid oedema; treat with oral antihistamines only', false, 'Ruled out because a preceding insect bite with erythema (not simply itching/swelling) makes an infective cause more likely, and antibiotics rather than antihistamines alone are the appropriate treatment given the risk of progression.', 2),
('cf000000-0000-0000-0000-000000000016', 'C', 'Chalazion; manage with warm compresses only', false, 'Ruled out because this is diffuse eyelid swelling and erythema following a skin breach, not a discrete painless nodule; this pattern indicates cellulitis, not a chalazion.', 3),
('cf000000-0000-0000-0000-000000000016', 'D', 'Reassure and discharge with no treatment or follow-up', false, 'Ruled out because untreated preseptal cellulitis can progress to sight- and life-threatening orbital cellulitis; oral antibiotics and safety-netting/follow-up are required.', 4),
('cf000000-0000-0000-0000-000000000016', 'E', 'Preseptal cellulitis; treat with oral antibiotics and review closely for progression', true, 'Correct. Eyelid swelling and erythema following a skin breach (insect bite), with preserved visual acuity, normal pupils and full, pain-free eye movements and no proptosis, indicates infection confined to the tissues anterior to the orbital septum (preseptal/periorbital cellulitis). This is managed with oral antibiotics and close review, as it can progress to orbital cellulitis if not monitored.', 5),
('cf000000-0000-0000-0000-000000000017', 'A', 'Discharge home with a course of oral antibiotics and outpatient review in one week', false, 'Ruled out because the presence of proptosis, restricted painful eye movements and reduced vision indicates orbital (not simply preseptal) cellulitis, which is a sight- and life-threatening emergency requiring admission and intravenous treatment.', 1),
('cf000000-0000-0000-0000-000000000017', 'B', 'Reassure that this is simple allergic swelling and prescribe antihistamines', false, 'Ruled out because the systemic fever, proptosis, restricted painful eye movements and reduced vision are inconsistent with a benign allergic process and instead indicate a serious infective orbital emergency.', 2),
('cf000000-0000-0000-0000-000000000017', 'C', 'Emergency admission for intravenous antibiotics and urgent CT imaging of the orbits and sinuses', true, 'Correct. Proptosis, painful restricted eye movements, reduced visual acuity and fever following a recent sinus infection indicate orbital cellulitis, a sight- and life-threatening emergency (with risk of intracranial spread) usually arising from ethmoid sinusitis in children. It requires emergency admission, intravenous antibiotics, and urgent CT imaging to assess for an orbital abscess that may need surgical drainage.', 3),
('cf000000-0000-0000-0000-000000000017', 'D', 'Warm compresses and review in the community in 48 hours', false, 'Ruled out because this presentation requires immediate hospital admission for intravenous antibiotics and imaging, not conservative outpatient measures with delayed review.', 4),
('cf000000-0000-0000-0000-000000000017', 'E', 'Arrange an outpatient MRI in the next available slot with no immediate treatment', false, 'Ruled out because orbital cellulitis is a same-day emergency requiring immediate admission, intravenous antibiotics and urgent imaging; delaying to an outpatient slot risks blindness, abscess formation, and intracranial extension.', 5),
('cf000000-0000-0000-0000-000000000018', 'A', 'Acute dacryocystitis', true, 'Correct. A painful, red swelling localised over the lacrimal sac (medial canthus, below the medial palpebral ligament) with discharge expressible from the punctum, in a patient with pre-existing chronic epiphora (suggesting underlying nasolacrimal duct obstruction), is characteristic of acute dacryocystitis - infection of an obstructed, stagnant lacrimal sac.', 1),
('cf000000-0000-0000-0000-000000000018', 'B', 'Preseptal cellulitis', false, 'Ruled out because preseptal cellulitis causes diffuse eyelid swelling, not a discrete swelling localised precisely over the lacrimal sac with expressible discharge from the punctum.', 2),
('cf000000-0000-0000-0000-000000000018', 'C', 'Chalazion', false, 'Ruled out because a chalazion is a painless nodule within the eyelid tarsal plate, not a painful swelling over the lacrimal sac with associated discharge and preceding chronic watering.', 3),
('cf000000-0000-0000-0000-000000000018', 'D', 'Allergic conjunctivitis', false, 'Ruled out because allergic conjunctivitis causes bilateral itching and chemosis, not a unilateral painful swelling localised to the lacrimal sac.', 4),
('cf000000-0000-0000-0000-000000000018', 'E', 'Orbital cellulitis', false, 'Ruled out because there is no proptosis, painful or restricted eye movement, or visual disturbance described; the localised swelling over the lacrimal sac points specifically to dacryocystitis.', 5),
('cf000000-0000-0000-0000-000000000019', 'A', 'Arrange emergency referral for intravenous antibiotics', false, 'Ruled out because there are no signs of infection (no redness, swelling, or discharge, and the eye is white and quiet); this is a benign, self-limiting anatomical problem, not an infective emergency.', 1),
('cf000000-0000-0000-0000-000000000019', 'B', 'Refer immediately for surgical probing of the nasolacrimal duct', false, 'Ruled out because most cases of congenital nasolacrimal duct obstruction resolve spontaneously within the first year, so immediate surgical probing at 4 months is not the first-line approach; conservative management is appropriate initially.', 2),
('cf000000-0000-0000-0000-000000000019', 'C', 'Prescribe topical chloramphenicol drops as first-line treatment', false, 'Ruled out because there is no evidence of infection (no discharge or redness); antibiotics are not indicated for simple congenital duct obstruction without infective signs.', 3),
('cf000000-0000-0000-0000-000000000019', 'D', 'Reassure the parents and advise lacrimal sac massage, as most cases resolve spontaneously by 12 months of age', true, 'Correct. Persistent watering since birth in an otherwise white, quiet eye without redness or discharge is typical of congenital nasolacrimal duct obstruction, caused by a membrane failing to canalise at the lower end of the duct. The majority resolve spontaneously within the first year of life, so conservative management with lacrimal sac massage and reassurance is appropriate, reserving probing for those that persist beyond about 12 months.', 4),
('cf000000-0000-0000-0000-000000000019', 'E', 'Refer urgently to exclude retinoblastoma', false, 'Ruled out because there is no leukocoria or abnormal red reflex described; the clinical picture is one of simple epiphora from duct obstruction, not an intraocular tumour.', 5),
('cf000000-0000-0000-0000-000000000020', 'A', 'Reassure that this is a chalazion and manage with warm compresses', false, 'Ruled out because a chalazion is a painless, non-ulcerated, mobile nodule that typically resolves over weeks, not a slowly enlarging, ulcerated, pearly lesion present for many months with lash loss.', 1),
('cf000000-0000-0000-0000-000000000020', 'B', 'Urgent (2-week-wait) referral for biopsy and likely surgical excision', true, 'Correct. A slowly growing, pearly, ulcerated nodule with telangiectasia and associated lash loss in an older patient with significant sun exposure is classic for basal cell carcinoma of the eyelid. This requires urgent referral for histological confirmation and surgical excision, as while BCC rarely metastasises, it can cause significant local tissue destruction if neglected, particularly around the eye.', 2),
('cf000000-0000-0000-0000-000000000020', 'C', 'Prescribe topical antibiotic ointment and review in six weeks', false, $x$Ruled out because this lesion's appearance and chronicity are concerning for malignancy, not infection; topical antibiotics have no role, and delay risks local tissue invasion, particularly given the periocular location.$x$, 3),
('cf000000-0000-0000-0000-000000000020', 'D', 'Advise this is a normal sun-related skin change requiring no action', false, 'Ruled out because the described features (pearly nodule, central ulceration, telangiectasia, lash loss, slow growth over months) are red-flag features for skin malignancy requiring urgent referral, not reassurance.', 4),
('cf000000-0000-0000-0000-000000000020', 'E', 'Arrange routine (non-urgent) dermatology review in six months', false, 'Ruled out because suspected periocular basal cell carcinoma should be referred urgently (2-week-wait) given the risk of local invasion into orbital structures if left for months, not managed with a delayed routine referral.', 5),
('cf000000-0000-0000-0000-000000000021', 'A', 'Check visual acuity first, then arrange irrigation once documented', false, 'Ruled out because any delay in an alkali chemical injury allows ongoing tissue penetration and damage; irrigation must be started immediately and takes priority over formal visual acuity documentation.', 1),
('cf000000-0000-0000-0000-000000000021', 'B', 'Apply a firm eye pad and arrange transfer to an ophthalmology unit', false, 'Ruled out because padding the eye without irrigation leaves the alkali in contact with ocular tissue, continuing to cause damage; immediate irrigation is required first, not padding and transfer.', 2),
('cf000000-0000-0000-0000-000000000021', 'C', 'Immediate copious irrigation of the eye with saline or water, before formal visual acuity testing or detailed history', true, 'Correct. Wet cement is a strongly alkaline substance and alkali chemical injuries cause rapid, progressive penetration and liquefactive necrosis of ocular tissues. Immediate copious irrigation must begin at once, before any other assessment (including visual acuity testing, detailed history-taking or pH testing), as delay significantly worsens outcome; irrigation should continue until the pH is neutral.', 3),
('cf000000-0000-0000-0000-000000000021', 'D', 'Instil topical local anaesthetic drops and observe for one hour before further action', false, 'Ruled out because while topical anaesthetic may help with comfort during irrigation, the priority is to begin irrigation immediately, not to simply observe before treating the ongoing chemical injury.', 4),
('cf000000-0000-0000-0000-000000000021', 'E', 'Take a detailed history of the exact chemical composition before starting any treatment', false, 'Ruled out because irrigation must never be delayed to obtain a detailed history; treatment (irrigation) always takes priority over history-taking in chemical eye injuries.', 5),
('cf000000-0000-0000-0000-000000000022', 'A', 'Apply firm padding and pressure to control bleeding, then discharge with oral antibiotics', false, 'Ruled out because applying pressure to a ruptured globe can extrude intraocular contents and cause irreversible damage; a rigid shield without pressure is required, along with emergency surgical referral, not discharge.', 1),
('cf000000-0000-0000-0000-000000000022', 'B', 'Apply a protective rigid shield (avoiding any pressure on the eye), keep the patient nil by mouth, and arrange emergency referral to ophthalmology/vitreoretinal surgery', true, 'Correct. A full-thickness corneal laceration with a shallow anterior chamber and a peaked, irregular pupil indicates penetrating globe injury (globe rupture). The eye must be protected with a rigid shield without any pressure (no patching or attempts to examine further, and no measurement of intraocular pressure, as this can extrude intraocular contents), the patient kept nil by mouth in anticipation of emergency surgery, and urgent same-time referral made to ophthalmology.', 2),
('cf000000-0000-0000-0000-000000000022', 'C', 'Measure intraocular pressure to guide further management', false, 'Ruled out because measuring intraocular pressure in a suspected ruptured globe risks extruding intraocular contents through the wound and must be avoided; the priority is protection with a rigid shield and emergency referral.', 3),
('cf000000-0000-0000-0000-000000000022', 'D', 'Instil topical antibiotic drops liberally and arrange review the next day', false, 'Ruled out because a penetrating globe injury is a surgical emergency requiring immediate protection and same-time referral, not topical treatment with delayed review.', 4),
('cf000000-0000-0000-0000-000000000022', 'E', 'Attempt to remove the visible metal fragment with forceps in the emergency department', false, 'Ruled out because any manipulation of a penetrating eye injury outside a controlled theatre setting by an ophthalmic surgeon risks worsening prolapse of intraocular contents; this must be managed by ophthalmology in theatre.', 5),
('cf000000-0000-0000-0000-000000000023', 'A', 'Plain X-ray of the skull only', false, 'Ruled out because plain skull X-rays are insufficient to characterise orbital floor fractures and soft tissue entrapment; CT is required for adequate assessment.', 1),
('cf000000-0000-0000-0000-000000000023', 'B', 'MRI brain as first-line imaging', false, 'Ruled out because CT is the first-line and most practical imaging for acute facial/orbital bony trauma; MRI is not the initial investigation of choice in this acute trauma setting.', 2),
('cf000000-0000-0000-0000-000000000023', 'C', 'B-scan ocular ultrasound', false, 'Ruled out because ultrasound is not appropriate for assessing bony orbital fractures and infraorbital nerve involvement; CT of the orbits is required.', 3),
('cf000000-0000-0000-0000-000000000023', 'D', 'CT scan of the orbits and facial bones', true, 'Correct. Diplopia on upgaze, infraorbital (cheek and upper lip) numbness, and enophthalmos (sunken appearance) following blunt trauma are classic features of an orbital floor blow-out fracture, in which the inferior rectus/orbital tissue can become entrapped and the infraorbital nerve is damaged as it runs through the orbital floor. CT of the orbits and facial bones is the investigation of choice to define the fracture and any muscle entrapment, guiding further management (including maxillofacial/ophthalmology referral).', 4),
('cf000000-0000-0000-0000-000000000023', 'E', 'No imaging required; manage with observation alone', false, 'Ruled out because the combination of diplopia, sensory loss and enophthalmos suggests a significant orbital fracture that requires imaging to assess for entrapment and guide potential surgical management.', 5),
('cf000000-0000-0000-0000-000000000024', 'A', 'Reassure and discharge with no follow-up required, as hyphaema always resolves spontaneously', false, 'Ruled out because although many hyphaemas do resolve, there is a real risk of secondary haemorrhage and raised intraocular pressure that can threaten vision, so urgent ophthalmic assessment and follow-up are required rather than simple discharge.', 1),
('cf000000-0000-0000-0000-000000000024', 'B', 'Prescribe ibuprofen for pain relief and review in one week', false, 'Ruled out because NSAIDs increase bleeding risk and are best avoided in hyphaema; the patient also needs urgent (same-day), not delayed, ophthalmic assessment given the risk of rebleeding and raised pressure.', 2),
('cf000000-0000-0000-0000-000000000024', 'C', 'Patch the eye firmly and encourage early return to normal activity, including contact sports', false, 'Ruled out because firm patching is not required, and the patient should avoid strenuous activity/contact sports, which increases the risk of rebleeding, until cleared by ophthalmology.', 3),
('cf000000-0000-0000-0000-000000000024', 'D', 'Arrange non-urgent outpatient ophthalmology review within four weeks', false, 'Ruled out because hyphaema requires urgent, same-day assessment due to the risk of secondary bleeding and acutely raised intraocular pressure, not a delayed routine appointment.', 4),
('cf000000-0000-0000-0000-000000000024', 'E', 'Urgent same-day ophthalmology referral, with the patient advised to rest with the head elevated and avoid NSAIDs/aspirin', true, 'Correct. A visible layer of blood in the anterior chamber (hyphaema) following blunt trauma requires urgent same-day ophthalmic assessment, as it carries a risk of secondary (rebleeding) haemorrhage and raised intraocular pressure. The patient should rest with the head elevated to help the blood settle and should avoid NSAIDs/aspirin, which increase bleeding risk.', 5),
('cf000000-0000-0000-0000-000000000025', 'A', 'Removal of the foreign body under slit-lamp magnification with topical anaesthesia, followed by topical antibiotic ointment', true, 'Correct. A superficial corneal foreign body with an intact anterior chamber and no signs of penetration should be removed under slit-lamp magnification (using topical anaesthetic for comfort), with a topical antibiotic given afterwards to prevent secondary infection while the epithelium heals.', 1),
('cf000000-0000-0000-0000-000000000025', 'B', 'Immediate referral for surgical removal under general anaesthesia', false, 'Ruled out because a small, superficial corneal foreign body without signs of penetration can usually be removed safely at the slit lamp under topical anaesthesia in the emergency department or eye casualty; general anaesthesia is not required.', 2),
('cf000000-0000-0000-0000-000000000025', 'C', 'Firm eye padding for 48 hours without removing the foreign body', false, 'Ruled out because leaving a foreign body in place risks ongoing corneal damage, infection and rust ring formation (with metallic fragments); the foreign body should be removed promptly, not simply padded over.', 3),
('cf000000-0000-0000-0000-000000000025', 'D', 'Reassure that it will resolve on its own and no treatment or removal is needed', false, 'Ruled out because a retained corneal foreign body will not resolve spontaneously and risks worsening injury or infection; it requires prompt removal.', 4),
('cf000000-0000-0000-0000-000000000025', 'E', 'Start oral antiviral therapy for presumed herpetic keratitis', false, 'Ruled out because the clinical picture (recent metal-grinding injury, visible embedded foreign body) points to a traumatic corneal foreign body, not herpes simplex keratitis, which would show a dendritic ulcer pattern rather than a foreign body.', 5),
('cf000000-0000-0000-0000-000000000026', 'A', 'Arrange urgent CT imaging first, and delay any intervention until results are available', false, 'Ruled out because when there are clinical signs of orbital compartment syndrome (worsening vision, tense proptosed globe, RAPD), decompression must not be delayed for imaging; canthotomy and cantholysis should be performed immediately, with imaging obtained afterwards.', 1),
('cf000000-0000-0000-0000-000000000026', 'B', 'Emergency lateral canthotomy and cantholysis without waiting for imaging', true, $x$Correct. Rapidly progressive proptosis, a tense globe, worsening vision, and a new relative afferent pupillary defect after trauma indicate orbital compartment syndrome from a retrobulbar haemorrhage, an ophthalmic emergency where rising orbital pressure compromises the optic nerve's blood supply. Emergency decompression by lateral canthotomy and cantholysis must be performed immediately at the bedside, without waiting for CT imaging, as any delay risks permanent blindness.$x$, 2),
('cf000000-0000-0000-0000-000000000026', 'C', 'Apply a firm pressure pad to the eye to control any bleeding', false, 'Ruled out because applying pressure to an already tense, compartment-syndrome eye will worsen the intraorbital pressure and further compromise the optic nerve; this is contraindicated.', 3),
('cf000000-0000-0000-0000-000000000026', 'D', 'Administer high-dose intravenous corticosteroids alone and observe', false, 'Ruled out because steroids do not provide the immediate mechanical decompression required to relieve a rapidly rising, vision-threatening orbital compartment pressure; emergency canthotomy and cantholysis is required.', 4),
('cf000000-0000-0000-0000-000000000026', 'E', 'Refer for outpatient ophthalmology review within 24 hours', false, 'Ruled out because this is a same-minute surgical emergency requiring immediate bedside decompression to prevent irreversible optic nerve damage, not a delayed outpatient review.', 5),
('cf000000-0000-0000-0000-000000000027', 'A', 'Bacterial keratitis; start empirical intensive topical antibiotics and refer urgently', false, 'Ruled out because bacterial keratitis typically presents with a focal corneal infiltrate/ulcer, often unilateral and associated with contact lens wear, rather than bilateral diffuse punctate staining occurring hours after UV exposure.', 1),
('cf000000-0000-0000-0000-000000000027', 'B', 'Herpes simplex keratitis; start oral antivirals immediately', false, 'Ruled out because HSV keratitis typically causes a unilateral dendritic corneal ulcer, not bilateral diffuse punctate staining temporally linked to unprotected UV exposure.', 2),
('cf000000-0000-0000-0000-000000000027', 'C', 'Acute angle closure glaucoma; start emergency IOP-lowering treatment', false, 'Ruled out because there is no fixed dilated pupil, hazy cornea from oedema, or markedly raised intraocular pressure described; the bilateral, symmetrical presentation after UV exposure points to photokeratitis, not angle closure.', 3),
('cf000000-0000-0000-0000-000000000027', 'D', 'Chemical eye injury; begin immediate copious irrigation', false, 'Ruled out because there is no history of chemical splash; the mechanism here is UV light exposure from welding, not a caustic substance, so irrigation is not the appropriate management, though supportive care is still needed.', 4),
('cf000000-0000-0000-0000-000000000027', 'E', $x$UV keratitis (photokeratitis, 'arc eye'); manage with lubricants, oral analgesia and topical antibiotic, expecting resolution within 24-48 hours$x$, true, $x$Correct. Bilateral pain, photophobia and diffuse punctate corneal staining occurring several hours after unprotected exposure to intense ultraviolet light (from welding arcs) is characteristic of UV keratitis ('arc eye' or photokeratitis). It is managed supportively with lubricants, oral analgesia, and sometimes a topical antibiotic for comfort/infection prevention, with resolution typically expected within 24-48 hours as the corneal epithelium regenerates.$x$, 5),
('cf000000-0000-0000-0000-000000000028', 'A', 'Bacterial conjunctivitis', false, 'Ruled out because bacterial conjunctivitis causes mucopurulent discharge with diffuse conjunctival injection but not photophobia, a small irregular pupil, or anterior chamber cells, which indicate intraocular inflammation.', 1),
('cf000000-0000-0000-0000-000000000028', 'B', 'Acute angle closure glaucoma', false, 'Ruled out because angle closure causes a markedly raised intraocular pressure with a fixed, mid-dilated pupil and a hazy cornea, differing from the small pupil and anterior chamber cells seen here, and it is not typically triggered in this delayed fashion by blunt trauma.', 2),
('cf000000-0000-0000-0000-000000000028', 'C', 'Traumatic anterior uveitis (iritis)', true, 'Correct. Photophobia, aching pain, ciliary flush, a small/irregular pupil and anterior chamber cells developing in the days following blunt ocular trauma are characteristic of traumatic iritis, an inflammatory reaction of the anterior uvea triggered by the contusion injury.', 3),
('cf000000-0000-0000-0000-000000000028', 'D', 'Retinal detachment', false, 'Ruled out because retinal detachment presents with flashes, floaters and a field defect, not photophobia with anterior chamber inflammation and a small irregular pupil.', 4),
('cf000000-0000-0000-0000-000000000028', 'E', 'Hyphaema', false, 'Ruled out because hyphaema is a visible layer of blood in the anterior chamber, which is explicitly absent here; the described cells in the anterior chamber without blood indicate inflammation (iritis), not haemorrhage.', 5),
('cf000000-0000-0000-0000-000000000029', 'A', 'Simple closure with standard sutures in the emergency department with no further referral', false, 'Ruled out because a medial lid laceration near the punctum risks unrecognised canalicular injury; simple closure without specialist assessment risks permanent tear drainage dysfunction, so referral to a specialist is required.', 1),
('cf000000-0000-0000-0000-000000000029', 'B', 'Steri-strips only, with no formal wound exploration', false, 'Ruled out because adhesive strips are inadequate for a full-thickness lid laceration, and importantly this location requires formal exploration to assess for canalicular involvement, which needs specialist repair.', 2),
('cf000000-0000-0000-0000-000000000029', 'C', 'Reassure the parents that this will heal without any intervention', false, 'Ruled out because a full-thickness eyelid laceration, especially medially near the tear drainage system, requires formal surgical assessment and repair; it will not appropriately heal on its own without risking a poor functional and cosmetic outcome.', 3),
('cf000000-0000-0000-0000-000000000029', 'D', 'Referral to an ophthalmologist/oculoplastic specialist for exploration and repair, as the lacrimal canaliculus may be involved', true, 'Correct. A medial eyelid laceration near the punctum raises strong suspicion of canalicular (tear drainage) system injury. This requires specialist ophthalmic/oculoplastic assessment and repair (often with stenting of the canaliculus), as simple suturing without recognising and repairing canalicular injury can result in permanent epiphora from a strictured or non-functioning drainage system.', 4),
('cf000000-0000-0000-0000-000000000029', 'E', 'Prescribe oral antibiotics only and review in the community in one week', false, 'Ruled out because antibiotics alone do not address the structural laceration and possible canalicular injury, which needs specialist surgical exploration and repair, ideally soon after injury.', 5),
('cf000000-0000-0000-0000-000000000030', 'A', 'Reassure the patient that this is a simple subconjunctival haemorrhage that will resolve spontaneously, as vision, pupil and the posterior extent of the haemorrhage are all normal', true, 'Correct. An isolated subconjunctival haemorrhage after minor trauma, with normal visual acuity, a normal pupil, and a fully visualised posterior extent (excluding an underlying scleral laceration hidden behind the haemorrhage), can be safely reassured and managed conservatively, as it will resorb over one to two weeks without treatment.', 1),
('cf000000-0000-0000-0000-000000000030', 'B', 'Arrange emergency CT orbits, as any subconjunctival haemorrhage after trauma indicates globe rupture', false, 'Ruled out because most subconjunctival haemorrhages after minor trauma are benign, especially when vision, pupil reaction and the posterior extent of the haemorrhage (indicating no hidden scleral injury) are normal; CT is reserved for cases with red flag features suggesting a more serious injury.', 2),
('cf000000-0000-0000-0000-000000000030', 'C', 'Apply a rigid shield and refer immediately for open globe repair', false, 'Ruled out because there is no evidence of a ruptured globe here (normal vision, normal pupil, fully visible posterior extent of the bleed, no laceration); this benign finding does not require shielding or emergency surgical referral.', 3),
('cf000000-0000-0000-0000-000000000030', 'D', 'Start topical corticosteroid drops immediately to hasten resolution', false, 'Ruled out because a simple subconjunctival haemorrhage resolves spontaneously without any treatment; topical steroids are unnecessary and not first-line for this benign finding.', 4),
('cf000000-0000-0000-0000-000000000030', 'E', 'Perform urgent intraocular pressure measurement and dilated fundoscopy before allowing discharge', false, 'Ruled out because in this reassuring presentation (normal vision, normal pupil, visible posterior extent of the haemorrhage, no red flags), extensive additional testing before discharge is not necessary; reassurance and safety-netting are sufficient.', 5),
('cf000000-0000-0000-0000-000000000031', 'A', 'Reassure the mother that this is a normal variant that will resolve without any assessment', false, 'Ruled out because although some intermittent squints in very young infants can be normal, a squint persisting over two months confirmed on formal cover testing at age 3 needs assessment, given the real risk of amblyopia if left untreated.', 1),
('cf000000-0000-0000-0000-000000000031', 'B', 'Arrange urgent CT brain imaging before any ophthalmic assessment', false, 'Ruled out because most childhood concomitant squints are due to refractive error or other benign causes rather than intracranial pathology; the priority is orthoptic/ophthalmic assessment first, with imaging reserved for atypical (e.g., sudden onset, incomitant, or associated neurological signs) presentations.', 2),
('cf000000-0000-0000-0000-000000000031', 'C', 'Start patching of the unaffected right eye immediately without formal assessment', false, 'Ruled out because occlusion therapy should be guided by formal orthoptic/ophthalmic assessment (including refraction) rather than started empirically in primary care without proper evaluation.', 3),
('cf000000-0000-0000-0000-000000000031', 'D', 'Advise eye exercises at home with no referral needed', false, 'Ruled out because concomitant squint requires formal orthoptic/ophthalmic assessment (which may reveal a refractive cause needing glasses, and guides occlusion therapy) rather than unsupervised home exercises.', 4),
('cf000000-0000-0000-0000-000000000031', 'E', 'Refer to an orthoptist/paediatric ophthalmology service for assessment', true, 'Correct. A consistent inward deviation of one eye confirmed on cover testing in a young child indicates a concomitant convergent squint (esotropia). Prompt referral to orthoptics/paediatric ophthalmology is essential, as squint in childhood carries a significant risk of amblyopia (permanent reduction in vision in the deviating eye) if not assessed and treated during the critical period of visual development.', 5),
('cf000000-0000-0000-0000-000000000032', 'A', 'Patching of the amblyopic (right) eye rather than the good eye', false, 'Ruled out because patching the amblyopic eye would deprive the weaker eye of visual stimulation and worsen the problem; the good eye is patched to force use of the amblyopic eye.', 1),
('cf000000-0000-0000-0000-000000000032', 'B', 'Reassure that no further treatment is needed once glasses are provided', false, 'Ruled out because although correcting refractive error is an important first step, occlusion therapy of the good eye is often still required to actively strengthen vision in the amblyopic eye.', 2),
('cf000000-0000-0000-0000-000000000032', 'C', 'Arrange surgical correction of the squint as the sole treatment for amblyopia', false, 'Ruled out because squint surgery addresses ocular alignment/cosmesis but does not treat amblyopia itself; occlusion therapy (and optical correction) are needed to improve vision in the amblyopic eye.', 3),
('cf000000-0000-0000-0000-000000000032', 'D', 'Occlusion (patching) therapy of the good (left) eye for a prescribed number of hours per day', true, 'Correct. Once refractive error has been corrected with glasses, the standard treatment for amblyopia is occlusion therapy: patching the better-seeing eye to force the brain to use and strengthen the visual pathways of the amblyopic eye. This is most effective when started during the critical period of visual development (typically before around 7-8 years of age).', 4),
('cf000000-0000-0000-0000-000000000032', 'E', 'Delay any further treatment until the child is a teenager, when compliance will be better', false, 'Ruled out because amblyopia treatment is most effective within the critical period of visual development in early childhood; delaying treatment into the teenage years significantly reduces the chance of visual improvement.', 5),
('cf000000-0000-0000-0000-000000000033', 'A', 'Reassure the parents that this is a common photographic artefact and no referral is needed', false, 'Ruled out because while flash photography can occasionally produce artefacts, a consistently white reflex on direct clinical examination of the pupil must never be dismissed, as it is the classic sign of retinoblastoma and requires urgent referral.', 1),
('cf000000-0000-0000-0000-000000000033', 'B', 'Arrange routine ophthalmology outpatient review in three months', false, 'Ruled out because leukocoria requires urgent (not routine, delayed) referral, as retinoblastoma is time-critical to diagnose and treat for both survival and vision/eye preservation.', 2),
('cf000000-0000-0000-0000-000000000033', 'C', 'Urgent (2-week-wait) referral to paediatric ophthalmology', true, 'Correct. Leukocoria (a white pupillary reflex, absent normal red reflex) noticed in a photograph or on examination in an infant is a classic presenting sign of retinoblastoma, a potentially life-threatening intraocular malignancy of childhood. This requires urgent same-pathway (2-week-wait) referral to paediatric ophthalmology for prompt assessment, as early diagnosis significantly improves both survival and the chance of preserving the eye/vision.', 3),
('cf000000-0000-0000-0000-000000000033', 'D', 'Prescribe topical antibiotic drops for presumed conjunctivitis', false, 'Ruled out because there is no discharge, redness, or infective feature described; a white pupillary reflex indicates an intraocular problem requiring urgent specialist assessment, not topical antibiotics.', 4),
('cf000000-0000-0000-0000-000000000033', 'E', 'Advise the parents this can only be a congenital cataract and arrange non-urgent referral', false, 'Ruled out because while congenital cataract is one differential for leukocoria, retinoblastoma cannot be excluded without specialist assessment, and the possibility of malignancy makes urgent (not non-urgent) referral essential.', 5),
('cf000000-0000-0000-0000-000000000034', 'A', 'Congenital cataract; urgent referral to paediatric ophthalmology for assessment and likely early surgery', true, 'Correct. An abnormal (white/dull) red reflex noted at the newborn check is a key sign of congenital cataract, among other causes of leukocoria. Urgent referral to paediatric ophthalmology is required, as visually significant congenital cataracts need prompt (often within weeks) surgical removal to allow normal visual development and prevent irreversible amblyopia (deprivation amblyopia) from occurring during this critical period.', 1),
('cf000000-0000-0000-0000-000000000034', 'B', 'Reassure the parents that an abnormal red reflex is a common normal finding in newborns', false, 'Ruled out because an abnormal red reflex is never a normal finding and always requires prompt ophthalmic assessment to identify potentially serious causes such as congenital cataract or retinoblastoma.', 2),
('cf000000-0000-0000-0000-000000000034', 'C', 'Arrange routine ophthalmology follow-up at the 6-week baby check only', false, 'Ruled out because visually significant congenital cataract needs prompt assessment and treatment (ideally within the first weeks of life) to prevent irreversible deprivation amblyopia; waiting until the 6-week check risks a worse visual outcome.', 3),
('cf000000-0000-0000-0000-000000000034', 'D', 'Prescribe topical antibiotic drops for a presumed eye infection', false, 'Ruled out because there is no discharge or redness suggesting infection; the abnormal red reflex indicates a structural intraocular problem requiring urgent specialist referral, not antibiotics.', 4),
('cf000000-0000-0000-0000-000000000034', 'E', 'Advise this will resolve spontaneously as the eye develops', false, 'Ruled out because congenital cataract does not resolve spontaneously and, if visually significant, requires timely surgical intervention to prevent permanent visual impairment.', 5),
('cf000000-0000-0000-0000-000000000035', 'A', 'No screening is required, as ROP only affects term infants', false, 'Ruled out because retinopathy of prematurity specifically affects preterm and low-birth-weight infants, particularly those needing supplemental oxygen; it does not typically affect term infants, and this baby clearly meets screening criteria.', 1),
('cf000000-0000-0000-0000-000000000035', 'B', 'Arrange screening for retinopathy of prematurity according to local neonatal protocol, based on gestational age and birth weight criteria', true, $x$Correct. This infant meets standard criteria for retinopathy of prematurity (ROP) screening (born before 32 weeks' gestation and/or very low birth weight, with supplemental oxygen exposure as an additional risk factor). ROP is caused by abnormal retinal vascular development in preterm infants and can progress to retinal detachment and blindness if untreated, so timely screening according to local protocol (typically beginning at a defined postnatal or postmenstrual age) is essential to allow timely laser treatment if needed.$x$, 2),
('cf000000-0000-0000-0000-000000000035', 'C', 'Delay any eye examination until the child starts school', false, 'Ruled out because ROP can progress rapidly in the neonatal period and requires screening within a defined early postnatal window, with treatment (e.g., laser) needed promptly if significant disease is found; waiting until school age would allow blinding disease to progress untreated.', 3),
('cf000000-0000-0000-0000-000000000035', 'D', 'Arrange only a red reflex check at the 6-week baby check, with no formal ROP screening', false, 'Ruled out because a simple red reflex check is not sufficiently sensitive for ROP staging; formal dilated retinal screening by an ophthalmologist, following local protocol based on gestational age/birth weight, is required.', 4),
('cf000000-0000-0000-0000-000000000035', 'E', 'Reassure the parents that ROP risk is unrelated to oxygen therapy', false, 'Ruled out because supplemental oxygen exposure is a recognised risk factor contributing to abnormal retinal vessel development in ROP, alongside prematurity and low birth weight.', 5),
('cf000000-0000-0000-0000-000000000036', 'A', 'Concomitant esotropia', false, 'Ruled out because concomitant squints have a constant angle of deviation in all directions of gaze and are not typically caused by trauma or associated with a specific worsening on down-gaze and compensatory head tilt, unlike this incomitant, trauma-related pattern.', 1),
('cf000000-0000-0000-0000-000000000036', 'B', 'Blepharitis', false, 'Ruled out because blepharitis causes lid margin inflammation and irritation, not diplopia or ocular misalignment.', 2),
('cf000000-0000-0000-0000-000000000036', 'C', 'Amblyopia', false, 'Ruled out because amblyopia is a unilateral reduction in visual acuity from disrupted visual development, not an acute onset of diplopia and gaze-dependent misalignment following trauma.', 3),
('cf000000-0000-0000-0000-000000000036', 'D', 'Allergic conjunctivitis', false, 'Ruled out because this presents with itching and redness, not diplopia or ocular misalignment following head trauma.', 4),
('cf000000-0000-0000-0000-000000000036', 'E', 'Fourth cranial nerve (trochlear nerve) palsy', true, 'Correct. Vertical diplopia that worsens on down-gaze, with a compensatory head tilt to reduce double vision, following head trauma, is characteristic of a fourth (trochlear) nerve palsy affecting the superior oblique muscle. This is a form of incomitant (paralytic) strabismus, unlike the constant-angle concomitant squints typically seen in younger children without a specific muscle/nerve cause.', 5),
('cf000000-0000-0000-0000-000000000037', 'A', 'To screen for serious conditions such as congenital cataract and retinoblastoma that can present with an abnormal reflex', true, 'Correct. The red reflex test is a simple, rapid screening tool performed in the newborn (and 6-week) examination to detect an abnormal (dull, white, or asymmetric) reflex, which can indicate sight- or life-threatening conditions such as congenital cataract or retinoblastoma, allowing early referral and treatment.', 1),
('cf000000-0000-0000-0000-000000000037', 'B', $x$To measure the baby's visual acuity precisely$x$, false, 'Ruled out because the red reflex test does not quantify visual acuity; it is a screening test for structural abnormalities of the media (cornea, lens, vitreous) and posterior segment causing an abnormal reflex.', 2),
('cf000000-0000-0000-0000-000000000037', 'C', 'To check for signs of conjunctivitis only', false, 'Ruled out because conjunctivitis is diagnosed by looking for discharge and redness on external examination, not primarily through the red reflex test, which screens for deeper structural problems.', 3),
('cf000000-0000-0000-0000-000000000037', 'D', $x$To assess the baby's colour vision$x$, false, 'Ruled out because colour vision cannot be assessed in a newborn using the red reflex test; this is a screening tool for opacities/tumours in the visual pathway, not colour perception.', 4),
('cf000000-0000-0000-0000-000000000037', 'E', 'To confirm normal extraocular muscle function', false, 'Ruled out because extraocular muscle function and alignment are assessed separately (for example, by observing eye movements and later cover testing), not through the red reflex test.', 5),
('cf000000-0000-0000-0000-000000000038', 'A', 'Reassure the parents that nystagmus is a normal congenital finding requiring no further investigation', false, 'Ruled out because this is new-onset (acquired), not longstanding congenital, nystagmus, and it is accompanied by worrying systemic features (morning vomiting, ataxia) that strongly suggest an underlying neurological cause requiring urgent investigation.', 1),
('cf000000-0000-0000-0000-000000000038', 'B', 'Refer routinely to community optometry for a standard eye test', false, 'Ruled out because the combination of new nystagmus with vomiting and ataxia are red flag features requiring urgent neuroimaging, not a routine optometry appointment, which would dangerously delay diagnosis of a potentially serious intracranial cause.', 2),
('cf000000-0000-0000-0000-000000000038', 'C', 'Urgent referral for neuroimaging (MRI brain)', true, 'Correct. New-onset (acquired) nystagmus in a previously normal child, especially accompanied by early morning vomiting and new-onset ataxia (unsteadiness), is a red flag for raised intracranial pressure and posterior fossa pathology, such as a cerebellar tumour. This requires urgent neuroimaging to identify or exclude an intracranial cause, rather than being assumed to be a benign ocular condition.', 3),
('cf000000-0000-0000-0000-000000000038', 'D', 'Start prophylactic anti-emetic medication and review in the community in a month', false, 'Ruled out because treating the vomiting symptomatically without investigating the underlying cause would miss a potentially serious and treatable intracranial pathology; urgent imaging is required now.', 4),
('cf000000-0000-0000-0000-000000000038', 'E', 'Advise this is likely a viral illness and safety-net for review only if symptoms worsen', false, 'Ruled out because new nystagmus with ataxia and vomiting are red flag neurological features that require urgent same-pathway neuroimaging, not reassurance and passive safety-netting.', 5),
('cf000000-0000-0000-0000-000000000039', 'A', 'No eye monitoring is needed, as she has no eye symptoms', false, 'Ruled out because JIA-associated uveitis is classically asymptomatic in its early stages; relying on symptoms alone would miss silent inflammation that can cause irreversible damage, so scheduled screening regardless of symptoms is required.', 1),
('cf000000-0000-0000-0000-000000000039', 'B', 'She requires regular slit-lamp screening by ophthalmology, as JIA-associated anterior uveitis is often asymptomatic and can cause silent visual damage if undetected', true, 'Correct. Children with juvenile idiopathic arthritis, particularly oligoarticular JIA with positive ANA, are at significant risk of chronic anterior uveitis that is frequently asymptomatic (no redness or pain) despite causing ongoing intraocular inflammation. Regular slit-lamp screening by ophthalmology, at intervals determined by JIA subtype/ANA status/age and disease duration, is essential to detect and treat uveitis before it causes complications such as cataract, glaucoma or visual loss.', 2),
('cf000000-0000-0000-0000-000000000039', 'C', 'Eye monitoring is only needed if her joint disease becomes active again', false, 'Ruled out because uveitis activity does not reliably correlate with joint disease activity in JIA; she can have quiet joints but active, silent uveitis, so screening should continue on its own schedule regardless of joint status.', 3),
('cf000000-0000-0000-0000-000000000039', 'D', 'She should be screened only with a visual acuity check at her GP annually', false, 'Ruled out because simple visual acuity testing is not sensitive enough to detect early anterior chamber inflammation; formal slit-lamp examination by an ophthalmologist is required for adequate screening.', 4),
('cf000000-0000-0000-0000-000000000039', 'E', 'Screening can stop now that her arthritis is in clinical remission', false, 'Ruled out because uveitis risk persists independently of joint remission status and can develop or recur even when the joints are quiet, so regular screening should continue as per protocol, not be stopped based on joint remission alone.', 5),
('cf000000-0000-0000-0000-000000000040', 'A', 'True concomitant esotropia requiring urgent orthoptic referral', false, 'Ruled out because both the corneal light reflex test and the cover test are normal here, which excludes a true manifest squint; referral is not needed when these tests are normal and the appearance is explained by facial anatomy.', 1),
('cf000000-0000-0000-0000-000000000040', 'B', 'Fourth cranial nerve palsy', false, 'Ruled out because a nerve palsy would produce an incomitant deviation detectable on cover testing (and typically a compensatory head posture), neither of which is present here; the cover test is normal.', 2),
('cf000000-0000-0000-0000-000000000040', 'C', 'Congenital cataract requiring urgent ophthalmology referral', false, 'Ruled out because there is no mention of an abnormal red reflex or leukocoria; the concern here relates to apparent ocular alignment, which has been shown to be normal on examination.', 3),
('cf000000-0000-0000-0000-000000000040', 'D', 'Pseudostrabismus due to prominent epicanthic folds, with no true squint present', true, 'Correct. A symmetrical, centred corneal light reflex and a normal cover test (no movement of either eye on covering the other) confirm that there is no true ocular misalignment. The appearance of inward-turning eyes is an optical illusion caused by prominent epicanthic folds and a broad nasal bridge, which is common in infants and is termed pseudostrabismus; it does not require any treatment or referral, though it should still be confirmed on examination as done here.', 4),
('cf000000-0000-0000-0000-000000000040', 'E', 'Retinoblastoma requiring 2-week-wait referral', false, 'Ruled out because retinoblastoma presents with leukocoria (an abnormal white pupillary reflex), not with an appearance of inward eye turning explained by normal, symmetrical light reflexes and a normal cover test.', 5),
('cf000000-0000-0000-0000-000000000041', 'A', 'Reassure the patient this is a migraine and prescribe oral triptans', false, 'Ruled out because although headache and nausea/vomiting occur in migraine, the combination with a red eye, hazy cornea, fixed mid-dilated pupil and a hard globe indicates acute angle closure glaucoma, an emergency, not migraine.', 1),
('cf000000-0000-0000-0000-000000000041', 'B', 'Prescribe topical chloramphenicol for presumed bacterial conjunctivitis', false, 'Ruled out because bacterial conjunctivitis causes purulent discharge without severe pain, haloes, a fixed pupil or a hard globe; this presentation is an emergency requiring urgent IOP-lowering treatment, not antibiotics.', 2),
('cf000000-0000-0000-0000-000000000041', 'C', 'Arrange routine ophthalmology outpatient review within two weeks', false, 'Ruled out because acute angle closure glaucoma is a same-hour emergency requiring immediate treatment to prevent permanent visual loss; a delayed routine appointment is dangerously inappropriate.', 3),
('cf000000-0000-0000-0000-000000000041', 'D', 'Emergency referral to ophthalmology for immediate intraocular pressure-lowering treatment (e.g., topical and systemic agents)', true, 'Correct. Severe eye pain with headache, nausea/vomiting, haloes, a hazy cornea, a fixed mid-dilated pupil and a hard globe in a long-sighted (hypermetropic) older patient is the classic presentation of acute angle closure glaucoma. This is an ophthalmic emergency requiring immediate treatment to lower the acutely raised intraocular pressure (typically with topical agents, acetazolamide, and analgesia/antiemetics) and urgent ophthalmology involvement, as delay risks permanent optic nerve damage and blindness.', 4),
('cf000000-0000-0000-0000-000000000041', 'E', 'Administer high-dose oral corticosteroids and discharge with safety-net advice', false, 'Ruled out because corticosteroids do not lower the acutely raised intraocular pressure in angle closure glaucoma; the priority is emergency referral for specific pressure-lowering treatment.', 5),
('cf000000-0000-0000-0000-000000000042', 'A', 'Urgent same-day referral to ophthalmology for slit-lamp assessment', false, 'Ruled out because there are no red flag features here (normal vision, clear cornea, normal pupils, no significant pain or photophobia); this presentation can be safely managed in primary care without urgent referral.', 1),
('cf000000-0000-0000-0000-000000000042', 'B', 'Start oral antiviral therapy for presumed herpetic infection', false, 'Ruled out because the bilateral purulent discharge pattern here is typical of bacterial conjunctivitis, not the dendritic corneal ulceration of herpes simplex keratitis, so antivirals are not indicated.', 2),
('cf000000-0000-0000-0000-000000000042', 'C', 'Reassure that this is likely bacterial conjunctivitis, usually self-limiting, and offer topical chloramphenicol if symptoms are bothersome or not improving', true, 'Correct. Bilateral purulent discharge causing lids to stick together, with normal vision, a clear cornea and normal pupils, is typical of bacterial conjunctivitis, which is usually self-limiting within one to two weeks. Topical chloramphenicol can be offered to shorten the duration of symptoms or if it is not settling, but urgent referral is not required given the absence of any red flag features.', 3),
('cf000000-0000-0000-0000-000000000042', 'D', 'Prescribe topical corticosteroid drops as first-line treatment', false, 'Ruled out because topical steroids are not first-line for infective conjunctivitis and can worsen unrecognised herpetic or fungal infection; they should not be started in primary care without specialist assessment.', 4),
('cf000000-0000-0000-0000-000000000042', 'E', 'Admit for intravenous antibiotics', false, 'Ruled out because uncomplicated bacterial conjunctivitis is a mild, self-limiting condition managed in primary care with topical treatment; it does not require admission or intravenous antibiotics.', 5),
('cf000000-0000-0000-0000-000000000043', 'A', 'Viral conjunctivitis; manage supportively with lubricants and advise on hygiene measures to reduce spread', true, 'Correct. Watery discharge, a preceding upper respiratory tract infection, sequential spread between eyes, and a tender preauricular lymph node are characteristic of viral (commonly adenoviral) conjunctivitis. It is managed supportively with lubricating drops, cool compresses, and advice on strict hand hygiene, as it is highly contagious, with resolution typically expected over one to three weeks.', 1),
('cf000000-0000-0000-0000-000000000043', 'B', 'Bacterial conjunctivitis; prescribe topical chloramphenicol as first-line treatment', false, 'Ruled out because the watery (not purulent) discharge, associated upper respiratory symptoms, and preauricular lymphadenopathy are more typical of a viral cause; antibiotics have no benefit in viral conjunctivitis.', 2),
('cf000000-0000-0000-0000-000000000043', 'C', 'Allergic conjunctivitis; prescribe topical antihistamine drops', false, 'Ruled out because allergic conjunctivitis typically causes itching and bilateral chemosis without preceding systemic viral symptoms or preauricular lymphadenopathy, which point instead to a viral cause here.', 3),
('cf000000-0000-0000-0000-000000000043', 'D', 'Herpes simplex keratitis; start oral antivirals', false, 'Ruled out because there is no dendritic corneal ulcer described, and the systemic pattern (preceding cold symptoms, preauricular node, sequential spread) is typical of adenoviral conjunctivitis rather than HSV keratitis.', 4),
('cf000000-0000-0000-0000-000000000043', 'E', 'Acute angle closure glaucoma; refer for emergency IOP-lowering treatment', false, 'Ruled out because there is no severe pain, haloes, fixed pupil or hazy cornea; this is a benign, self-limiting infective conjunctivitis, not an emergency.', 5),
('cf000000-0000-0000-0000-000000000044', 'A', 'Topical chloramphenicol antibiotic drops', false, 'Ruled out because there is no infective process here; antibiotics have no role in allergic conjunctivitis, which is driven by an IgE-mediated hypersensitivity reaction, not infection.', 1),
('cf000000-0000-0000-0000-000000000044', 'B', 'Topical antihistamine or mast-cell stabiliser eye drops, alongside avoidance of triggers where possible', true, 'Correct. Bilateral itching (the hallmark symptom), watering and chemosis occurring seasonally alongside hay fever symptoms is characteristic of seasonal allergic conjunctivitis. First-line treatment is topical antihistamine or mast-cell stabiliser drops, combined with allergen avoidance where practical, with oral antihistamines added if there are prominent systemic allergic symptoms.', 2),
('cf000000-0000-0000-0000-000000000044', 'C', 'Topical corticosteroid drops as first-line treatment in primary care', false, 'Ruled out because although steroids can be effective for severe allergic eye disease, they are not first-line in primary care due to side effects (cataract, raised intraocular pressure) with prolonged use, and should generally be reserved for specialist-guided short courses in resistant cases.', 3),
('cf000000-0000-0000-0000-000000000044', 'D', 'Emergency referral for intraocular pressure-lowering treatment', false, 'Ruled out because there are no features of angle closure glaucoma (no severe pain, hazy cornea, or fixed pupil); this is a benign allergic condition managed in primary care.', 4),
('cf000000-0000-0000-0000-000000000044', 'E', 'Oral antiviral therapy', false, 'Ruled out because there is no viral infective process here; antivirals have no role in allergic conjunctivitis.', 5),
('cf000000-0000-0000-0000-000000000045', 'A', 'Scleritis; refer urgently to ophthalmology for assessment for systemic immunosuppression', false, 'Ruled out because scleritis typically causes severe, boring pain (often waking the patient at night), globe tenderness, and vessels that do NOT blanch with pressure, unlike the mild discomfort and blanching vessels described here, which favour the more benign episcleritis.', 1),
('cf000000-0000-0000-0000-000000000045', 'B', 'Bacterial conjunctivitis; prescribe topical chloramphenicol', false, 'Ruled out because bacterial conjunctivitis causes diffuse (not sectoral) injection with purulent discharge, which is not described here; the sectoral, blanching pattern is more typical of episcleritis.', 2),
('cf000000-0000-0000-0000-000000000045', 'C', 'Anterior uveitis; start topical cycloplegics and steroids urgently', false, 'Ruled out because uveitis presents with photophobia, ciliary injection and anterior chamber cells with a small pupil, none of which are present here; this well-defined blanching sectoral redness is typical of the more benign episcleritis.', 3),
('cf000000-0000-0000-0000-000000000045', 'D', 'Acute angle closure glaucoma; refer for emergency IOP-lowering treatment', false, 'Ruled out because there is no severe pain, haloes, hazy cornea, or fixed pupil; this mild, well-defined, blanching sectoral redness is not consistent with an emergency.', 4),
('cf000000-0000-0000-0000-000000000045', 'E', 'Episcleritis; reassure that it is usually self-limiting and manage with lubricants if mild discomfort persists', true, 'Correct. A well-defined, sectoral area of redness with only mild discomfort, no significant pain, normal vision, and vessels that blanch with gentle pressure is characteristic of episcleritis, a benign, usually self-limiting inflammation of the episclera. It typically resolves within one to two weeks with simple reassurance and lubricants; more persistent or recurrent cases may need topical NSAIDs.', 5),
('cf000000-0000-0000-0000-000000000046', 'A', 'Reassure that this is simple episcleritis and manage with lubricants alone', false, 'Ruled out because the severity of pain (waking the patient at night), globe tenderness and non-blanching vessels distinguish this from the milder, blanching, minimally painful presentation of episcleritis, and this requires urgent specialist assessment, not reassurance.', 1),
('cf000000-0000-0000-0000-000000000046', 'B', 'Prescribe topical chloramphenicol for presumed bacterial infection', false, 'Ruled out because there is no purulent discharge or infective feature; this presentation, especially with underlying rheumatoid arthritis, points to scleritis, an inflammatory/autoimmune process requiring urgent ophthalmic and often systemic treatment.', 2),
('cf000000-0000-0000-0000-000000000046', 'C', 'Advise simple oral paracetamol and review in the community in two weeks', false, 'Ruled out because scleritis can threaten vision and may signal active systemic vasculitis; it requires urgent same-day specialist assessment, not simple analgesia with delayed follow-up.', 3),
('cf000000-0000-0000-0000-000000000046', 'D', 'Urgent same-day referral to ophthalmology for assessment and consideration of systemic immunosuppressive treatment', true, 'Correct. Severe boring pain that wakes the patient at night, marked globe tenderness, and deep violaceous redness with non-blanching vessels, in a patient with rheumatoid arthritis, is characteristic of scleritis. This is a sight-threatening condition strongly associated with underlying systemic autoimmune/vasculitic disease and requires urgent same-day ophthalmology assessment, often needing systemic (not just topical) immunosuppressive treatment.', 4),
('cf000000-0000-0000-0000-000000000046', 'E', 'Start topical corticosteroid drops alone in primary care without referral', false, 'Ruled out because scleritis, particularly associated with rheumatoid arthritis, often requires systemic (not just topical) immunosuppressive treatment guided by ophthalmology, and initiating treatment without specialist assessment risks inadequate control and progression.', 5),
('cf000000-0000-0000-0000-000000000047', 'A', 'Acute anterior uveitis, likely HLA-B27-associated given the history of inflammatory back pain', true, 'Correct. Pain, photophobia, ciliary injection, a small poorly reactive pupil and anterior chamber cells, with a history of recurrent similar episodes and chronic inflammatory-type back pain (suggestive of axial spondyloarthritis/ankylosing spondylitis), is characteristic of acute anterior uveitis, which has a strong association with HLA-B27-related conditions.', 1),
('cf000000-0000-0000-0000-000000000047', 'B', 'Bacterial conjunctivitis', false, 'Ruled out because bacterial conjunctivitis causes purulent discharge with diffuse injection but not photophobia, a small poorly reactive pupil, or anterior chamber cells, which indicate intraocular inflammation rather than surface infection.', 2),
('cf000000-0000-0000-0000-000000000047', 'C', 'Acute angle closure glaucoma', false, 'Ruled out because angle closure typically causes a markedly raised intraocular pressure with a fixed, mid-dilated (not small) pupil and a hazy cornea, and lacks the recurrent pattern linked with inflammatory back pain seen here.', 3),
('cf000000-0000-0000-0000-000000000047', 'D', 'Viral conjunctivitis', false, 'Ruled out because viral conjunctivitis causes watery discharge and preauricular lymphadenopathy without significant photophobia, a small poorly reactive pupil, or anterior chamber inflammation.', 4),
('cf000000-0000-0000-0000-000000000047', 'E', 'Episcleritis', false, 'Ruled out because episcleritis causes mild, sectoral, blanching redness with minimal pain and no photophobia, pupil abnormality or anterior chamber cells, unlike this presentation.', 5),
('cf000000-0000-0000-0000-000000000048', 'A', 'Continue contact lens wear and prescribe lubricating drops only', false, 'Ruled out because continuing lens wear in the presence of a corneal infiltrate and hypopyon will worsen the infection and risks corneal perforation and permanent scarring/visual loss; lenses must be stopped immediately and urgent treatment started.', 1),
('cf000000-0000-0000-0000-000000000048', 'B', 'Prescribe a short course of topical corticosteroid drops as first-line treatment', false, 'Ruled out because topical steroids without concurrent antimicrobial cover can worsen an active corneal infection and are contraindicated as sole first-line therapy; this requires urgent ophthalmology assessment for antimicrobial treatment first.', 2),
('cf000000-0000-0000-0000-000000000048', 'C', 'Same-day emergency referral to ophthalmology, with the patient advised to stop wearing contact lenses immediately', true, 'Correct. Severe pain, a corneal infiltrate with an overlying epithelial defect, and hypopyon in a contact lens wearer (especially with overnight wear) is characteristic of bacterial (microbial) keratitis, a sight-threatening corneal infection. This requires same-day emergency ophthalmology referral for corneal scrape and culture, and intensive topical antibiotic treatment, with immediate cessation of contact lens wear.', 3),
('cf000000-0000-0000-0000-000000000048', 'D', 'Arrange routine (non-urgent) ophthalmology outpatient review within two weeks', false, 'Ruled out because bacterial keratitis is a sight-threatening emergency that can progress to corneal perforation within days; it requires same-day, not delayed, ophthalmic assessment.', 4),
('cf000000-0000-0000-0000-000000000048', 'E', 'Reassure that this is simple contact lens-related dryness and advise increasing lubricant use', false, 'Ruled out because the presence of a corneal infiltrate, epithelial defect and hypopyon indicates an infective corneal ulcer, not simple dryness, and requires emergency same-day referral, not reassurance.', 5),
('cf000000-0000-0000-0000-000000000049', 'A', 'Prescribe topical corticosteroid drops as first-line treatment', false, 'Ruled out because topical corticosteroids can significantly worsen herpes simplex keratitis, promoting viral replication and risking corneal melting/perforation; they should be avoided in this context unless specifically directed by ophthalmology alongside antivirals.', 1),
('cf000000-0000-0000-0000-000000000049', 'B', 'Prescribe topical chloramphenicol antibiotic drops only', false, 'Ruled out because this is a viral (herpetic), not bacterial, corneal infection; antibiotics alone will not treat the underlying herpes simplex virus, and topical antivirals are required.', 2),
('cf000000-0000-0000-0000-000000000049', 'C', 'Reassure that this will resolve without any specific treatment and review in one month', false, 'Ruled out because untreated herpes simplex keratitis can progress and cause corneal scarring with permanent visual impairment; prompt antiviral treatment and ophthalmology referral are needed.', 3),
('cf000000-0000-0000-0000-000000000049', 'D', 'Remove the corneal epithelium surgically as first-line management', false, 'Ruled out because surgical debridement is not the first-line treatment for a dendritic ulcer; topical antiviral therapy is the mainstay of initial management.', 4),
('cf000000-0000-0000-0000-000000000049', 'E', 'Start topical antiviral treatment and refer to ophthalmology, avoiding topical corticosteroids', true, 'Correct. A dendritic (branching, tree-like) corneal ulcer with reduced corneal sensation, in a patient with a recent history of cold sores (herpes labialis), is characteristic of herpes simplex keratitis. This is treated with topical antiviral agents and urgent ophthalmology referral; topical corticosteroids must be avoided (or used only under specialist guidance) as they can worsen herpetic corneal disease and risk progression to corneal perforation.', 5),
('cf000000-0000-0000-0000-000000000050', 'A', 'Reassure that this is a simple skin condition and no antiviral or ophthalmic referral is needed', false, $x$Ruled out because herpes zoster ophthalmicus, especially with Hutchinson's sign, carries a high risk of serious ocular complications (keratitis, uveitis, and rarely permanent visual loss) and requires prompt antiviral treatment and ophthalmic assessment.$x$, 1),
('cf000000-0000-0000-0000-000000000050', 'B', 'Start oral antiviral treatment promptly and refer urgently to ophthalmology for eye assessment', true, $x$Correct. A vesicular rash strictly confined to one side of the forehead/upper eyelid (trigeminal V1 dermatome) with a vesicle on the tip of the nose (Hutchinson's sign, indicating nasociliary nerve involvement and a high risk of ocular involvement) associated with a red, watering eye is characteristic of herpes zoster ophthalmicus. Prompt oral antiviral treatment (ideally started within 72 hours of rash onset) reduces the risk and severity of ocular complications, and urgent ophthalmology referral is needed to assess for and manage keratitis, uveitis or other ocular involvement.$x$, 2),
('cf000000-0000-0000-0000-000000000050', 'C', 'Prescribe topical antibiotic drops only, with no oral treatment', false, 'Ruled out because this is a viral (varicella zoster), not bacterial, process; oral antivirals are required to treat the underlying infection and reduce complication risk, not topical antibiotics alone.', 3),
('cf000000-0000-0000-0000-000000000050', 'D', 'Delay any treatment until vesicles have fully crusted over', false, 'Ruled out because antiviral treatment is most effective when started early (ideally within 72 hours of rash onset) to reduce the severity and complications of the infection, including ocular involvement; delaying treatment reduces its effectiveness.', 4),
('cf000000-0000-0000-0000-000000000050', 'E', 'Arrange routine ophthalmology review in one month with no immediate treatment', false, $x$Ruled out because the presence of Hutchinson's sign indicates a significant risk of sight-threatening ocular involvement requiring urgent (not delayed) assessment alongside prompt antiviral therapy.$x$, 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('cf000000-0000-0000-0000-000000000001', 'Giant cell arteritis causing arteritic AION is an ophthalmic emergency: give high-dose corticosteroids immediately on clinical suspicion, do not wait for biopsy or even ESR/CRP results if suspicion is high.', 1),
('cf000000-0000-0000-0000-000000000001', 'Jaw claudication and scalp tenderness alongside sudden visual loss in an older adult should always trigger urgent GCA workup, as the fellow eye can be lost within days without treatment.', 2),
('cf000000-0000-0000-0000-000000000001', 'Temporal artery biopsy should be arranged promptly but performed after steroids are started, as pathological changes persist for 1-2 weeks.', 3),
('cf000000-0000-0000-0000-000000000002', 'CRAO presents with sudden painless profound monocular visual loss and a pale retina with a cherry-red spot at the macula (the macula is thin and perfused by the choroid, so it stays red against the pale, ischaemic surrounding retina).', 1),
('cf000000-0000-0000-0000-000000000002', 'CRAO should be treated as a retinal stroke: urgent same-day referral for vascular work-up (carotid imaging, ECG/echo for AF or embolic source, stroke risk factor management) is essential even though visual recovery is often limited.', 2),
('cf000000-0000-0000-0000-000000000002', 'Untreated non-anticoagulated atrial fibrillation is an important embolic source to identify and address.', 3),
('cf000000-0000-0000-0000-000000000003', 'New-onset flashes and floaters followed by a progressive curtain-like or shadow field defect are the classic warning symptoms of rhegmatogenous retinal detachment and mandate same-day ophthalmic referral.', 1),
('cf000000-0000-0000-0000-000000000003', 'High myopia is a major risk factor for retinal detachment because of associated peripheral retinal thinning and vitreous changes.', 2),
('cf000000-0000-0000-0000-000000000003', 'The urgency is driven by macular status: while the macula is still attached, vision can often be preserved with prompt surgery, but once it detaches visual prognosis worsens significantly.', 3),
('cf000000-0000-0000-0000-000000000004', $x$CRVO classically produces a 'stormy sunset' fundus: widespread flame and blot haemorrhages in all quadrants, disc swelling, and dilated tortuous veins.$x$, 1),
('cf000000-0000-0000-0000-000000000004', 'Hypertension, diabetes, glaucoma and hyperviscosity states are the main risk factors for CRVO; blood pressure and glucose control should be optimised and the patient referred urgently to ophthalmology to assess for macular oedema and neovascular risk.', 2),
('cf000000-0000-0000-0000-000000000004', 'CRVO differs from CRAO (pale retina, cherry-red spot, no haemorrhages) which reflects arterial rather than venous occlusion.', 3),
('cf000000-0000-0000-0000-000000000005', $x$Vitreous haemorrhage typically presents with sudden painless floaters, 'cobwebs', or a red haze, and a hazy or absent red reflex due to blood in the vitreous cavity.$x$, 1),
('cf000000-0000-0000-0000-000000000005', 'Proliferative diabetic retinopathy causes fragile neovascular vessels that are prone to spontaneous bleeding, especially with poor glycaemic control and missed screening.', 2),
('cf000000-0000-0000-0000-000000000005', 'Any patient with diabetes and sudden visual loss needs urgent same-day ophthalmology referral, as vitreous haemorrhage may herald tractional retinal detachment and needs assessment (and sometimes laser or vitrectomy).', 3),
('cf000000-0000-0000-0000-000000000006', 'New metamorphopsia (distorted straight lines) or a new central scotoma in a patient with AMD suggests conversion to wet (neovascular) AMD and needs urgent same-week ophthalmology referral.', 1),
('cf000000-0000-0000-0000-000000000006', 'Anti-VEGF intravitreal injections are time-critical in wet AMD; delay allows further neovascular growth, haemorrhage and scarring with permanent loss of central vision.', 2),
('cf000000-0000-0000-0000-000000000006', 'Dry AMD progresses gradually over months to years, whereas sudden new distortion or a rapid drop in acuity should always raise suspicion of the wet form.', 3),
('cf000000-0000-0000-0000-000000000007', 'Optic neuritis classically presents with subacute painful monocular visual loss (worse on eye movement), reduced colour vision, and a relative afferent pupillary defect, often with a swollen or normal-looking disc.', 1),
('cf000000-0000-0000-0000-000000000007', 'MRI brain and orbits is the key investigation, as white matter lesions substantially increase the risk of subsequent multiple sclerosis.', 2),
('cf000000-0000-0000-0000-000000000007', 'A prior transient neurological episode (such as sensory disturbance) that was not investigated should raise suspicion of a previous demyelinating episode.', 3),
('cf000000-0000-0000-0000-000000000008', 'Amaurosis fugax is a form of TIA affecting the retinal circulation, presenting as transient, fully reversible monocular visual loss, often described as a curtain or shade.', 1),
('cf000000-0000-0000-0000-000000000008', 'It must be treated as a TIA: immediate aspirin (if no contraindication) and same-day specialist assessment, since it carries a significant short-term risk of stroke.', 2),
('cf000000-0000-0000-0000-000000000008', 'Carotid Doppler ultrasound is a key investigation to look for a source of embolism amenable to intervention (e.g., carotid endarterectomy).', 3),
('cf000000-0000-0000-0000-000000000009', 'Bilateral papilloedema with headache, and transient visual obscurations (brief greying/blacking out of vision, often with posture change), suggests raised intracranial pressure and idiopathic intracranial hypertension, more common in obese young women.', 1),
('cf000000-0000-0000-0000-000000000009', 'Neuroimaging (MRI with venography) must precede lumbar puncture to exclude a space-occupying lesion or venous sinus thrombosis, since LP in the presence of a mass can cause fatal herniation.', 2),
('cf000000-0000-0000-0000-000000000009', 'Untreated papilloedema can cause progressive, potentially permanent optic nerve damage and visual field loss, so prompt diagnosis and pressure-lowering treatment (e.g., acetazolamide, weight loss, or surgical options) is important.', 3),
('cf000000-0000-0000-0000-000000000010', 'Postoperative endophthalmitis typically presents within days of intraocular surgery with increasing pain, redness, marked visual decline and hypopyon, and is a same-day ophthalmic emergency.', 1),
('cf000000-0000-0000-0000-000000000010', 'Management requires urgent vitreous/aqueous sampling and immediate intravitreal (not oral or topical) antibiotics, sometimes alongside vitrectomy, to try to salvage vision.', 2),
('cf000000-0000-0000-0000-000000000010', 'This must be distinguished from expected mild postoperative inflammation, which does not cause hypopyon, systemic upset, or dramatic acuity loss.', 3),
('cf000000-0000-0000-0000-000000000011', 'Blepharitis presents with chronic bilateral gritty, burning eyes, crusting on waking, and lid margin telangiectasia/flaking, and is managed conservatively with lid hygiene.', 1),
('cf000000-0000-0000-0000-000000000011', 'It is a benign, chronic, relapsing condition and does not require urgent ophthalmology referral unless complications develop (e.g., corneal involvement or recurrent chalazia).', 2),
('cf000000-0000-0000-0000-000000000011', 'Warm compresses followed by mechanical lid margin cleaning form the mainstay of first-line treatment, sometimes supplemented by artificial tears for associated dry eye.', 3),
('cf000000-0000-0000-0000-000000000012', 'A chalazion is a painless, firm, chronic nodule from an obstructed meibomian gland, typically managed conservatively with warm compresses as most resolve without intervention.', 1),
('cf000000-0000-0000-0000-000000000012', 'This contrasts with a hordeolum (stye), which is an acutely painful, tender swelling at the lash margin from an infected gland.', 2),
('cf000000-0000-0000-0000-000000000012', 'Persistent chalazia unresponsive to conservative treatment, or those recurring in the same location in an older patient, may need incision/curettage or biopsy to exclude a sebaceous gland carcinoma mimicking a chalazion.', 3),
('cf000000-0000-0000-0000-000000000013', 'A hordeolum (stye) is a painful, tender, pointing swelling at the eyelash margin from acute infection of a lash follicle or associated gland, unlike the painless deep nodule of a chalazion.', 1),
('cf000000-0000-0000-0000-000000000013', 'First-line management is warm compresses; topical antibiotics are added if there is associated conjunctivitis or if it fails to settle.', 2),
('cf000000-0000-0000-0000-000000000013', 'Absence of proptosis, painful eye movements or visual change helps exclude the more serious differential of orbital cellulitis.', 3),
('cf000000-0000-0000-0000-000000000014', 'Entropion is inward turning of the eyelid margin, most commonly involutional (age-related) in older adults, causing lashes to rub the cornea and risking corneal abrasion or ulceration if untreated.', 1),
('cf000000-0000-0000-0000-000000000014', 'Temporary taping of the lid can relieve symptoms while awaiting definitive surgical correction, which is the usual definitive treatment.', 2),
('cf000000-0000-0000-0000-000000000014', 'This is the mirror-image condition to ectropion (outward lid turning), which causes exposure keratopathy and epiphora rather than lash-corneal irritation.', 3),
('cf000000-0000-0000-0000-000000000015', 'Ectropion is outward turning of the eyelid margin, commonly caused by age-related laxity, but also by facial nerve palsy (paralytic ectropion) due to orbicularis oculi weakness.', 1),
('cf000000-0000-0000-0000-000000000015', $x$It leads to poor lid apposition, exposure of the ocular surface, epiphora, and risk of exposure keratopathy if the cornea is inadequately protected, especially with reduced blink and Bell's phenomenon.$x$, 2),
('cf000000-0000-0000-0000-000000000015', 'Lubricants and eye protection (e.g., taping at night) are used while awaiting specialist assessment and possible surgical correction, especially if corneal exposure risk is significant.', 3),
('cf000000-0000-0000-0000-000000000016', 'Preseptal cellulitis causes eyelid swelling and erythema with normal vision, normal pupils, and full, pain-free eye movements, distinguishing it from orbital cellulitis.', 1),
('cf000000-0000-0000-0000-000000000016', 'It is managed with oral antibiotics in most children, but any progression to reduced acuity, proptosis, or painful/restricted eye movements should prompt urgent escalation as it may indicate orbital cellulitis.', 2),
('cf000000-0000-0000-0000-000000000016', 'A preceding skin breach (insect bite, minor trauma, or sinusitis) is a common precipitant.', 3),
('cf000000-0000-0000-0000-000000000017', 'Orbital cellulitis is distinguished from preseptal cellulitis by proptosis, painful or restricted eye movements, and reduced visual acuity, and is a same-day emergency.', 1),
('cf000000-0000-0000-0000-000000000017', 'It commonly arises from spread of infection from the paranasal sinuses (especially ethmoid sinusitis) in children and requires admission for intravenous antibiotics and urgent CT to assess for abscess and orbital/intracranial extension.', 2),
('cf000000-0000-0000-0000-000000000017', 'Complications include abscess formation, cavernous sinus thrombosis, and permanent visual loss if treatment is delayed.', 3),
('cf000000-0000-0000-0000-000000000018', 'Acute dacryocystitis presents as a painful, red swelling precisely over the lacrimal sac (below the medial palpebral ligament), often with expressible discharge from the punctum.', 1),
('cf000000-0000-0000-0000-000000000018', 'It usually occurs in the context of pre-existing nasolacrimal duct obstruction causing chronic epiphora, which allows stagnant tears to become infected.', 2),
('cf000000-0000-0000-0000-000000000018', 'Management is with systemic antibiotics, with surgical drainage or later dacryocystorhinostomy considered if it recurs or an abscess forms.', 3),
('cf000000-0000-0000-0000-000000000019', 'Congenital nasolacrimal duct obstruction causes persistent watering from birth in an otherwise white, non-inflamed eye, and the majority resolve spontaneously by around 12 months of age.', 1),
('cf000000-0000-0000-0000-000000000019', 'First-line management is conservative: lacrimal sac massage and parental reassurance; probing is reserved for cases persisting beyond infancy.', 2),
('cf000000-0000-0000-0000-000000000019', 'The absence of redness, discharge, or photophobia helps distinguish this benign condition from infective or inflammatory causes of a watery eye.', 3),
('cf000000-0000-0000-0000-000000000020', 'Basal cell carcinoma classically presents as a slowly growing, pearly nodule with rolled edges, central ulceration, and fine telangiectasia, often with associated lash loss when it occurs at the eyelid margin.', 1),
('cf000000-0000-0000-0000-000000000020', 'It rarely metastasises but can cause significant local destruction, especially periocularly where it threatens the globe and orbital structures if neglected, so urgent (2-week-wait) referral for biopsy and excision is required.', 2),
('cf000000-0000-0000-0000-000000000020', 'Chronic sun exposure is the principal risk factor, and the lower eyelid is the most commonly affected periocular site.', 3),
('cf000000-0000-0000-0000-000000000021', 'Chemical eye injury (especially alkali, e.g. cement, plaster, drain cleaner) is a true ocular emergency where immediate copious irrigation takes absolute priority over history, visual acuity testing, or examination.', 1),
('cf000000-0000-0000-0000-000000000021', 'Alkali burns are generally more damaging than acid burns because they cause liquefactive necrosis and can penetrate the eye rapidly, continuing to cause damage as long as contact persists.', 2),
('cf000000-0000-0000-0000-000000000021', 'Irrigation should continue until the conjunctival pH is confirmed neutral (checked with litmus paper after irrigation, not before starting it), and the upper/lower fornices should be swept to remove any retained solid particles.', 3),
('cf000000-0000-0000-0000-000000000022', 'Suspected globe rupture (irregular/peaked pupil, shallow anterior chamber, visible laceration, or reduced vision after penetrating trauma) requires immediate protection with a rigid shield and avoidance of any pressure on the eye.', 1),
('cf000000-0000-0000-0000-000000000022', 'Intraocular pressure must never be measured in a suspected open globe injury, as this risks extruding intraocular contents.', 2),
('cf000000-0000-0000-0000-000000000022', 'The patient should be kept nil by mouth and referred emergently for surgical repair under general anaesthesia, ideally with antiemetics given (as vomiting raises intraocular pressure) and tetanus status checked.', 3),
('cf000000-0000-0000-0000-000000000023', 'Orbital blow-out fracture classically presents after blunt trauma with diplopia (especially on upgaze from inferior rectus involvement), infraorbital hypoaesthesia (infraorbital nerve damage), and enophthalmos.', 1),
('cf000000-0000-0000-0000-000000000023', 'CT of the orbits/facial bones is the investigation of choice to define the fracture and assess for muscle entrapment.', 2),
('cf000000-0000-0000-0000-000000000023', 'Any suspected orbital fracture should also prompt a full ophthalmic examination to exclude an associated globe injury, and referral to maxillofacial/ophthalmology teams for further management.', 3),
('cf000000-0000-0000-0000-000000000024', 'Hyphaema (blood in the anterior chamber) after blunt trauma requires urgent same-day ophthalmology assessment due to the risk of secondary haemorrhage and acutely raised intraocular pressure.', 1),
('cf000000-0000-0000-0000-000000000024', 'Patients should rest with head elevation, avoid NSAIDs/aspirin (which increase bleeding risk), and avoid strenuous activity until cleared, to reduce the risk of rebleeding.', 2),
('cf000000-0000-0000-0000-000000000024', 'Ophthalmology will monitor intraocular pressure closely, as significant elevation can threaten the optic nerve and requires prompt treatment.', 3),
('cf000000-0000-0000-0000-000000000025', 'Superficial corneal foreign bodies causing foreign body sensation, watering and photophobia are removed under slit-lamp magnification with topical anaesthesia, followed by topical antibiotic cover.', 1),
('cf000000-0000-0000-0000-000000000025', 'Metallic foreign bodies can leave a rust ring that may need further removal if not fully cleared initially; follow-up is arranged to check healing.', 2),
('cf000000-0000-0000-0000-000000000025', 'Signs suggesting a deeper or penetrating injury (irregular pupil, shallow anterior chamber, visible full-thickness defect) should prompt urgent ophthalmology referral rather than removal in a non-specialist setting.', 3),
('cf000000-0000-0000-0000-000000000026', 'Orbital compartment syndrome from retrobulbar haemorrhage presents with rapidly worsening proptosis, a tense globe, declining vision and a new relative afferent pupillary defect after trauma.', 1),
('cf000000-0000-0000-0000-000000000026', 'Emergency lateral canthotomy and inferior (and if needed superior) cantholysis is a bedside sight-saving procedure that must be performed immediately on clinical grounds, without waiting for imaging.', 2),
('cf000000-0000-0000-0000-000000000026', 'Delay in decompression risks permanent optic nerve ischaemia and blindness, since rising orbital pressure compromises retinal and optic nerve blood flow.', 3),
('cf000000-0000-0000-0000-000000000027', $x$UV keratitis ('arc eye') presents with bilateral pain, photophobia and diffuse punctate corneal staining several hours after unprotected exposure to intense UV light, such as from welding arcs or sunbeds/snow glare.$x$, 1),
('cf000000-0000-0000-0000-000000000027', 'Management is supportive (lubricants, oral analgesia, sometimes topical antibiotic) with expected resolution within 24-48 hours as the corneal epithelium heals.', 2),
('cf000000-0000-0000-0000-000000000027', 'Prevention with appropriate UV-protective eyewear is key, and recurrent or non-resolving cases should be reassessed to exclude other corneal pathology.', 3),
('cf000000-0000-0000-0000-000000000028', 'Traumatic iritis typically develops in the days following blunt ocular trauma, presenting with photophobia, aching pain, ciliary (circumcorneal) injection, a small or irregular pupil, and anterior chamber cells on slit-lamp examination.', 1),
('cf000000-0000-0000-0000-000000000028', 'It is treated with cycloplegic drops (to relieve ciliary spasm and pain) and topical corticosteroids under specialist guidance, with intraocular pressure monitored.', 2),
('cf000000-0000-0000-0000-000000000028', 'Any history of trauma with delayed-onset pain and photophobia should prompt slit-lamp assessment for anterior chamber inflammation, distinguishing it from the immediate mechanical injuries (hyphaema, globe rupture) seen straight after trauma.', 3),
('cf000000-0000-0000-0000-000000000029', 'Eyelid lacerations located medially, near the punctum or canaliculi, carry a risk of lacrimal drainage system injury and should be referred to an ophthalmologist/oculoplastic surgeon for careful exploration and repair.', 1),
('cf000000-0000-0000-0000-000000000029', 'Missed canalicular injury can result in permanent epiphora due to scarring or obstruction of the tear drainage pathway.', 2),
('cf000000-0000-0000-0000-000000000029', 'Lacerations involving the eyelid margin, tarsal plate, or with suspected orbital septum penetration also warrant specialist assessment rather than simple primary care closure.', 3),
('cf000000-0000-0000-0000-000000000030', 'An isolated subconjunctival haemorrhage after trauma is benign if vision, pupil reactions are normal and the posterior extent of the haemorrhage can be fully visualised (excluding a hidden scleral laceration underneath it).', 1),
('cf000000-0000-0000-0000-000000000030', 'Red flags that should prompt urgent referral instead include reduced visual acuity, an irregular or poorly reactive pupil, inability to see the full posterior extent of the haemorrhage, or a history suggesting a penetrating mechanism.', 2),
('cf000000-0000-0000-0000-000000000030', 'Reassurance is appropriate for simple cases, as the blood typically resolves spontaneously over one to two weeks without treatment.', 3),
('cf000000-0000-0000-0000-000000000031', 'A cover test is used to confirm a squint clinically: when the fixing eye is covered, the deviating eye moves to take up fixation.', 1),
('cf000000-0000-0000-0000-000000000031', 'Childhood squint should be assessed promptly by orthoptics/ophthalmology because of the risk of amblyopia, a permanent reduction in vision from disrupted visual development if not treated within the critical period.', 2),
('cf000000-0000-0000-0000-000000000031', 'Refractive error is a common underlying cause of concomitant squint and is corrected first, with occlusion (patching) therapy used to treat any resulting amblyopia.', 3),
('cf000000-0000-0000-0000-000000000032', 'Amblyopia treatment involves correcting any refractive error first, then occlusion (patching) of the better-seeing eye to strengthen the weaker (amblyopic) eye.', 1),
('cf000000-0000-0000-0000-000000000032', 'Treatment is most successful when started early, within the critical period of visual development (roughly up to age 7-8), as the visual system becomes far less plastic afterwards.', 2),
('cf000000-0000-0000-0000-000000000032', 'Squint surgery may be performed for ocular alignment but does not itself treat amblyopia, which requires occlusion/optical management.', 3),
('cf000000-0000-0000-0000-000000000033', 'Leukocoria (a white pupillary reflex/absent red reflex) is the classic presenting sign of retinoblastoma and must always trigger urgent same-pathway referral to paediatric ophthalmology.', 1),
('cf000000-0000-0000-0000-000000000033', 'Other causes of leukocoria include congenital cataract and retinopathy of prematurity, but these cannot be safely distinguished from retinoblastoma without specialist examination, so urgency is the same.', 2),
('cf000000-0000-0000-0000-000000000033', 'Early diagnosis of retinoblastoma is critical for both survival (it can be life-threatening if untreated) and for maximising the chance of preserving vision and the eye.', 3),
('cf000000-0000-0000-0000-000000000034', 'The red reflex test is a key part of the newborn and 6-week baby checks, screening for serious conditions such as congenital cataract and retinoblastoma that present with an abnormal (white/dull) reflex.', 1),
('cf000000-0000-0000-0000-000000000034', 'Visually significant congenital cataract requires prompt surgery, ideally within the first weeks to months of life, to prevent irreversible deprivation amblyopia during the critical period of visual development.', 2),
('cf000000-0000-0000-0000-000000000034', 'Any abnormal red reflex, regardless of family history, warrants urgent ophthalmology referral rather than reassurance or delayed follow-up.', 3),
('cf000000-0000-0000-0000-000000000035', 'Retinopathy of prematurity screening is indicated for infants born very preterm and/or with very low birth weight, with supplemental oxygen exposure as an added risk factor, following local/national protocol for timing.', 1),
('cf000000-0000-0000-0000-000000000035', 'ROP results from abnormal, disordered retinal vascular development and can progress to retinal detachment and blindness if severe disease is not identified and treated (e.g., with laser) in time.', 2),
('cf000000-0000-0000-0000-000000000035', 'Formal dilated retinal examination by an ophthalmologist, not a simple red reflex check, is required for adequate ROP screening and staging.', 3),
('cf000000-0000-0000-0000-000000000036', 'Fourth (trochlear) nerve palsy causes vertical diplopia worse on down-gaze and on head tilt towards the affected side, often with a compensatory head tilt away from the affected side to minimise symptoms.', 1),
('cf000000-0000-0000-0000-000000000036', 'It is a form of incomitant (paralytic) strabismus, where the degree of misalignment varies with gaze direction, in contrast to concomitant squints where the deviation is constant in all directions.', 2),
('cf000000-0000-0000-0000-000000000036', 'New incomitant strabismus, particularly after trauma or with other neurological features, warrants specialist ophthalmic/neurological assessment.', 3),
('cf000000-0000-0000-0000-000000000037', 'The red reflex test screens for serious conditions presenting with leukocoria, including congenital cataract and retinoblastoma, and is a routine part of newborn and 6-week baby checks.', 1),
('cf000000-0000-0000-0000-000000000037', 'Any abnormal, dull, white, or asymmetric red reflex warrants urgent referral to paediatric ophthalmology, regardless of family history.', 2),
('cf000000-0000-0000-0000-000000000037', 'Early detection through this simple screening test allows timely treatment, which is critical for both visual outcome (in cataract) and survival (in retinoblastoma).', 3),
('cf000000-0000-0000-0000-000000000038', 'Acquired (new-onset) nystagmus in a previously normal child, especially with associated features such as vomiting, headache, or ataxia, should be considered a red flag for intracranial pathology (e.g., posterior fossa tumour) until proven otherwise, warranting urgent neuroimaging.', 1),
('cf000000-0000-0000-0000-000000000038', 'This contrasts with congenital nystagmus, present from early infancy, which is often benign but should still be formally assessed at least once.', 2),
('cf000000-0000-0000-0000-000000000038', 'Early morning vomiting and new ataxia are classic features of raised intracranial pressure/cerebellar dysfunction and should never be dismissed as a simple viral illness in this context.', 3),
('cf000000-0000-0000-0000-000000000039', 'JIA-associated anterior uveitis, especially in young ANA-positive girls with oligoarticular disease, is frequently asymptomatic and is detected only through scheduled slit-lamp screening, not by waiting for symptoms.', 1),
('cf000000-0000-0000-0000-000000000039', 'Screening frequency is determined by JIA subtype, age of onset, ANA status and disease duration, and continues regardless of joint disease activity or remission.', 2),
('cf000000-0000-0000-0000-000000000039', 'Untreated silent uveitis can lead to serious complications including cataract, glaucoma, band keratopathy and permanent visual loss, making regular screening essential.', 3),
('cf000000-0000-0000-0000-000000000040', 'Pseudostrabismus is a common cause of parental concern about squint in infants, usually due to a broad nasal bridge and prominent epicanthic folds creating an illusion of misalignment.', 1),
('cf000000-0000-0000-0000-000000000040', 'The corneal light reflex (Hirschberg) test and cover test are simple, key clinical tools to distinguish true strabismus from pseudostrabismus; both are normal in pseudostrabismus.', 2),
('cf000000-0000-0000-0000-000000000040', 'Even when pseudostrabismus is suspected, a normal examination should be confirmed and documented, as intermittent or subtle true squints can sometimes be missed without formal testing.', 3),
('cf000000-0000-0000-0000-000000000041', 'Acute angle closure glaucoma presents with severe pain, headache, nausea/vomiting, haloes around lights, a hazy cornea, a fixed mid-dilated pupil, and a hard (tender) globe, typically in older, hypermetropic patients.', 1),
('cf000000-0000-0000-0000-000000000041', 'This is a same-hour ophthalmic emergency requiring immediate intraocular pressure-lowering treatment (topical drops, systemic acetazolamide) and urgent ophthalmology referral, followed by definitive treatment such as peripheral iridotomy once the acute attack settles.', 2),
('cf000000-0000-0000-0000-000000000041', 'It should always be considered in a patient presenting with headache and vomiting alongside a painful red eye, as it can otherwise be misdiagnosed as a primary headache disorder or gastrointestinal illness.', 3),
('cf000000-0000-0000-0000-000000000042', 'Bacterial conjunctivitis typically causes bilateral purulent/mucopurulent discharge with lids sticking together, but preserved vision, a clear cornea and normal pupils, and it is usually self-limiting.', 1),
('cf000000-0000-0000-0000-000000000042', 'Topical antibiotics such as chloramphenicol can shorten the duration but are not always necessary; the main value of assessment is to exclude red flag features requiring urgent referral (reduced vision, photophobia, corneal involvement, or a fixed/irregular pupil).', 2),
('cf000000-0000-0000-0000-000000000042', 'Good hand hygiene should be advised, as bacterial and viral conjunctivitis are both contagious.', 3),
('cf000000-0000-0000-0000-000000000043', 'Viral conjunctivitis typically presents with watery discharge, a preceding viral illness, sequential involvement of both eyes, and tender preauricular lymphadenopathy, and is managed supportively.', 1),
('cf000000-0000-0000-0000-000000000043', 'It is highly contagious, so hygiene advice (frequent handwashing, avoiding towel-sharing, temporary avoidance of school/work if appropriate) is important to reduce spread.', 2),
('cf000000-0000-0000-0000-000000000043', 'Antibiotics have no role in viral conjunctivitis, and topical steroids should be avoided in primary care due to the risk of worsening an unrecognised herpetic infection.', 3),
('cf000000-0000-0000-0000-000000000044', 'Itching is the hallmark symptom that distinguishes allergic conjunctivitis from infective causes of red eye, often with a seasonal pattern and other atopic features (hay fever, chemosis).', 1),
('cf000000-0000-0000-0000-000000000044', 'First-line treatment is topical antihistamine/mast-cell stabiliser drops and trigger avoidance, with topical steroids reserved for severe, specialist-guided cases due to their side-effect profile.', 2),
('cf000000-0000-0000-0000-000000000044', 'Vision and corneal clarity are preserved in uncomplicated allergic conjunctivitis, helping to distinguish it from more serious causes of red eye.', 3),
('cf000000-0000-0000-0000-000000000045', 'Episcleritis causes sectoral, often blanching, mild redness with minimal discomfort and preserved vision, and is usually self-limiting.', 1),
('cf000000-0000-0000-0000-000000000045', 'It is distinguished from scleritis, which causes severe pain (often nocturnal), globe tenderness, and non-blanching vessels, and which requires urgent ophthalmology assessment given associations with systemic vasculitic/autoimmune disease.', 2),
('cf000000-0000-0000-0000-000000000045', 'A simple test of gentle pressure through the lower lid, causing blanching of the vessels, supports episcleritis over the more serious scleritis.', 3),
('cf000000-0000-0000-0000-000000000046', 'Scleritis presents with severe, boring pain (often nocturnal), marked globe tenderness, and deep, non-blanching violaceous redness, and requires urgent same-day ophthalmology referral.', 1),
('cf000000-0000-0000-0000-000000000046', 'It is strongly associated with systemic autoimmune and vasculitic conditions (such as rheumatoid arthritis, granulomatosis with polyangiitis), and management often involves systemic immunosuppression, not just topical treatment.', 2),
('cf000000-0000-0000-0000-000000000046', 'The non-blanching test (gentle pressure through the lower lid) helps distinguish scleritis from the more benign, blanching episcleritis.', 3),
('cf000000-0000-0000-0000-000000000047', 'Acute anterior uveitis presents with pain, photophobia, ciliary injection, a small or irregular poorly reactive pupil, and anterior chamber cells/flare on slit-lamp examination.', 1),
('cf000000-0000-0000-0000-000000000047', 'It is strongly associated with HLA-B27-related conditions, including ankylosing spondylitis, and recurrent episodes (sometimes alternating eyes) are common in this group.', 2),
('cf000000-0000-0000-0000-000000000047', 'Management (usually by ophthalmology) includes cycloplegic drops (to relieve pain and prevent synechiae) and topical corticosteroids, with screening for an underlying systemic association if recurrent or bilateral.', 3),
('cf000000-0000-0000-0000-000000000048', 'Bacterial (microbial) keratitis presents with severe pain, a corneal white/grey infiltrate with an overlying epithelial defect, and sometimes hypopyon, and is a sight-threatening emergency requiring same-day ophthalmology referral.', 1),
('cf000000-0000-0000-0000-000000000048', 'Contact lens wear, particularly with poor hygiene or overnight/extended wear, is a major risk factor, and lenses must be discontinued immediately.', 2),
('cf000000-0000-0000-0000-000000000048', 'Management requires corneal scraping for microbiological diagnosis and intensive topical antimicrobial treatment; topical steroids are avoided until infection is controlled, as they can worsen the infective process.', 3),
('cf000000-0000-0000-0000-000000000049', 'Herpes simplex keratitis classically presents with a dendritic (branching) corneal ulcer on fluorescein staining and reduced corneal sensation, often with a history of cold sores or previous herpetic eye disease.', 1),
('cf000000-0000-0000-0000-000000000049', 'Topical antivirals are first-line treatment; topical corticosteroids should be avoided or used only under specialist supervision, as they can worsen the disease and risk corneal perforation.', 2),
('cf000000-0000-0000-0000-000000000049', 'Recurrent herpetic keratitis can cause corneal scarring and long-term visual impairment, so prompt ophthalmology involvement and follow-up are important.', 3),
('cf000000-0000-0000-0000-000000000050', 'Herpes zoster ophthalmicus involves the ophthalmic division (V1) of the trigeminal nerve, causing a vesicular rash strictly confined to one side, and can cause serious ocular complications including keratitis and uveitis.', 1),
('cf000000-0000-0000-0000-000000000050', $x$Hutchinson's sign (vesicles on the tip or side of the nose, indicating nasociliary nerve involvement) is associated with a significantly higher risk of ocular involvement and should prompt urgent ophthalmology referral.$x$, 2),
('cf000000-0000-0000-0000-000000000050', 'Oral antivirals are most effective when started within 72 hours of rash onset and reduce both the severity of the zoster and the risk of long-term ocular complications.', 3);
